pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // if they cannot accommodate common item sizes (harmonic classes).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins with enough space to fit it.
    // If the current post_residual is too small for the next item, penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            score -= 15.0;
        }
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the ones 
    // that are already close to the mean residual to keep fragmentation uniform.
    let dev_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current 
    // fitting options are extremely poor (i.e., would result in high fragmentation).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin. Only pick this if existing bins
        // force a high post_residual penalty.
        score = 45.0; 
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits the item, 
    // heavily reward choosing it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progress Scaling: As the stream nears the end, become more aggressive 
    // about packing tightly to minimize leftover bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic penalty: Heavily penalize residuals that are small but not zero (fragmentation)
    // We favor "Perfect Fits" (post_residual == 0) or large residuals that can accommodate future items.
    if post_residual > 0 {
        score += (bin_capacity as f64 / (post_residual as f64 + 1.0)).powf(1.5);
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize placements that block it.
    // If the next item cannot fit in the post_residual, apply a penalty proportional to the item's size.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64) * 1.5;
    }

    // 3. Capacity Fractioning: Prefer bins that align with the mean residual of the system
    // to keep the bin occupancy balanced, preventing outliers.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. Scarcity/Opening Logic:
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // reward it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Heuristic:
    // When evaluating a brand-new bin (bin_residual == bin_capacity),
    // we only return a low score if the item is large or the system is highly fragmented.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high to encourage Best-Fit.
        score = 80.0 + (item_size as f64 * 0.5);

        // If we have many open bins that are nearly full, opening a new one might be better.
        if mean_residual < 20.0 && open_bins_count > 5 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tightly packed.
    // 2. Lookahead Synergy: If the next item fits into the current post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Global State Balancing: If we have many open bins, prioritize filling existing ones.
    // If few bins are open, be more selective to avoid fragmentation.
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += density_factor * 2.5;

    // 4. New Bin Thresholding: If this is a new bin (residual == capacity),
    // only choose it if the current best available bin creates a "dead zone" (e.g., residual < 10).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && mean_residual > 15.0 {
            score += 100.0; // Heavily penalize opening a new bin if existing ones have room.
        } else {
            score -= 5.0; // Otherwise, keep it as a viable fallback.
        }
    }

    // 5. Fragmentation Avoidance: If the post_residual is small but > 0, it's often a "dead" space.
    // Discourage creating residuals between 1 and 9.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // 6. Temporal Scaling: As we approach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals) which are hard to fill.
    // The penalty is non-linear: smaller residuals are penalized exponentially as they approach 0.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powf(2.0) * 2.0;
    }

    // Lookahead logic: If the next item is large, penalize small post_residuals in the current bin
    // because they won't accommodate the future item.
    if next_item_size > 0 {
        let fit_penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 1.5
        } else {
            0.0
        };
        score += fit_penalty;
    }

    // Dynamic thresholding based on stream progress:
    // As the stream nears the end, become more aggressive about filling existing bins
    // to avoid leaving too many half-empty bins open.
    let exhaustion_factor = (1.0 - progress) * open_bins_count as f64;
    score += exhaustion_factor * (post / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it.
    // Only open a new bin if the current fit is significantly worse than the average residual.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other bins can fit the item.
        let new_bin_base_cost = 45.0;
        score = new_bin_base_cost + (mean_residual * 0.5);

        // If we are at the end of the stream, increase the cost to force packing into existing bins.
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // A base score of post_residual (Best Fit) is the foundation, 
    // but we adjust based on packing efficiency and lookahead.
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we are nearing the end of the stream.
        score += 45.0 + (mean_residual * 0.5) - (progress * 20.0);
    } else {
        // 2. Reward bins that leave a residual capable of fitting the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0;
            } else {
                // Penalize fragmenting space that could have been useful
                score += 10.0;
            }
        }

        // 3. Prefer bins that are already "tight" (Best Fit refinement)
        // If this bin is the last chance for the current item, prioritize it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // 4. Dynamic pressure: As the stream progresses, prioritize closing bins
        // (Reducing the number of open bins reduces fragmentation)
        score += (open_bins_count as f64) * 0.5;
    }

    // 5. Non-linear coupling: avoid creating "slivers" (very small residuals)
    // A residual between 1 and 9 is often useless for items 10-80
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps (1..10)
    // and balance against the total number of bins currently in use to avoid fragmentation.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is in the "unusable" range (1-9), 
    // it is highly likely to be wasted. We penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual,
    // reward this placement to keep the bin useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Open bin pressure: If we are close to the end of the stream, prioritize 
    // filling existing bins. If we are early, prioritize tight fits to save space.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // reduce the penalty for a poor fit to ensure we don't unnecessarily open new bins.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 40.0;
    }

    // 5. New Bin logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only choose a new bin if the score is significantly better than existing options.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, adjusted by how many bins are already open.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (dead space)
    // The "Sweet Spot" for remaining space is usually 0 or large enough for future items.
    // We heavily penalize post_residuals in the range [1, 9] as they are rarely useful.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_residual as f64) * 20.0
    } else {
        0.0
    };

    // Reward tighter fits (Best Fit principle)
    // As progress increases, become more aggressive about filling bins (Best Fit)
    // vs early on where we might prefer to keep bins balanced.
    let fit_reward = post_res * (1.0 + progress);

    // Lookahead logic: if the next item could fit in the current post_residual, 
    // prioritize this bin to maximize bin utilization.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -50.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a cost that 
    // decreases as the number of open bins increases (to avoid fragmentation).
    let new_bin_cost = if bin_residual == bin_capacity {
        150.0 - (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Interaction with mean_residual:
    // If the bin is emptier than the mean, it's a "fresher" bin, potentially better for large items.
    let mean_deviation_penalty = if bin_residual as f64 > mean_residual {
        (bin_residual as f64 - mean_residual) * 0.5
    } else {
        0.0
    };

    fit_reward + dead_space_penalty + lookahead_bonus + new_bin_cost + mean_deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for leaving "dead space" that is too small for common items,
    // weighted by progression through the stream.
    if post > 0.0 && post < 15.0 {
        score += (20.0 - post).powf(1.5) * (1.0 + progress);
    }

    // Lookahead logic: if next_item_size is large, penalize bins that leave 
    // too little space to accommodate it.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post > 0.0 && post < next {
            score += (next - post) * 2.5;
        }
    }

    // Encourage keeping the mean residual low as the stream progresses.
    // If this bin's post-residual is significantly higher than the mean, penalize it.
    if post > mean_residual {
        score += (post - mean_residual) * progress;
    }

    // Discourage opening a new bin prematurely.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy 
    // dynamic penalty that decreases as the stream nears the end.
    if bin_residual == bin_capacity {
        // We only consider opening a new bin if the current fit is terrible.
        // The threshold for "terrible" is adjusted by progress.
        let new_bin_base_cost = 25.0 + (1.0 - progress) * 20.0;
        score += new_bin_base_cost;
    }

    // Favor bins that have very little space left if fitting_bins_count is high.
    // This helps concentrate usage into fewer bins.
    if fitting_bins_count > 1 {
        score += (1.0 / (post + 1.0)) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": residuals too small for typical items (e.g., < 15)
    // are often worse than slightly larger residuals unless they hit exactly 0.
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res) * 2.0;
    }

    // Lookahead coupling: if the next item is large, prioritize keeping the residual 
    // large enough to accommodate it, or pack tightly if the current fit is near perfect.
    if next_item_size > 0 {
        let diff = (post_res as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5 * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive about
    // packing into existing bins to minimize the total count of open bins.
    let density_penalty = (open_bins_count as f64 / (1.0 + mean_residual)) * progress * 10.0;
    score += density_penalty;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold.
    // We only open a new bin if the "cost" of the best existing fit is worse than this constant.
    if bin_residual == bin_capacity {
        // As progress increases, the cost to open a new bin increases to force consolidation.
        score = 25.0 + (progress * 50.0);
    }

    // If this bin is the last chance for the current item, reduce penalty to prevent 
    // creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins where post_residual is minimal.
    // However, avoid creating "slivers" (very small residuals that nothing can fit into).
    // If post_residual is between 1 and 9, penalize it heavily as these are "dead" spaces.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalty for bins that cannot fit the next item if we have other options.
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), only pick it if current open bins are "crowded".
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high.
        score = 85.0; 
        // If we have few open bins, opening a new one is expensive.
        // If we have many open bins, opening a new one might be better than bad fragmentation.
        score -= (open_bins_count as f64 * 0.5);
    }

    // 4. Fitting Bin Scarcity:
    // If this is the ONLY bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual balancing:
    // Favor bins that keep the overall mean residual consistent.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progress weighting:
    // Toward the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger residuals (Best Fit logic)
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // We penalize residuals in the [1, 9] range as they are statistically hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item could potentially fit into this specific post-residual,
    // we reward this placement to keep bins tightly packed.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / 100.0);
    }

    // Dynamic scaling based on stream progress:
    // Early in the stream, prioritize aggressive packing. 
    // Late in the stream, be more permissive to avoid opening new bins.
    let tightness_factor = (open_bins_count as f64 / (1.0 + progress * 10.0)).powf(1.5);
    score += tightness_factor * (mean_residual - post);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decays as the stream progresses, effectively forcing the heuristic to
    // exhaust existing bins before opening new ones.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress.powf(0.5));
    }

    // Favor bins that are the "last chance" (fitting_bins_count == 1) to prevent fragmentation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in [1, 15], it's a "poisoned" bin.
    if post_residual > 0 && post_residual < 16 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly in the remaining space, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward slots that leave exactly enough space for the next item, 
