    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin unless the existing options are very cramped.
            score += 65.0;
        }
    }

    // 4. Density Balancing: Favor bins that stay near the global mean residual to reduce variance.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression Scaling: As the stream nears completion, become more aggressive at closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

