    // 4. Thresholding New Bins: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit is terrible (e.g., forces a small residual in all others)
        // or if we are nearing the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0; // Base cost to open a new bin
        score -= progress * 10.0; // Become more aggressive at opening new bins as stream ends
    } else {
        // If this bin is the only one that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Harmonic Modulo Logic: Reward bins that align with common item size factors (e.g., 20, 25, 33).
    // This helps pack items that are multiples of these values together.
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small gaps that cannot fit future items.
    // We treat post_residual as the base cost.
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is small but > 0, it's likely "toxic" space.
    // We penalize values between 1 and 9 (since min item size is likely 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item cannot fit in this post_residual, 
    // we penalize this bin slightly to favor bins that leave room for the lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Open bins pressure: As the stream progresses, we want to consolidate into fewer bins.
    // If this is a new bin (bin_residual == bin_capacity), penalize it relative to open_bins_count.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit is truly terrible or we have few open bins.
        score += (open_bins_count as f64) * 2.5;

        // If there are other bins that could fit this item, make the new bin very expensive.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Reward filling existing bins to reduce open_bins_count.
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. Mean residual alignment: Avoid bins that deviate significantly from the mean,
    // as uniform filling typically leads to better packing efficiency.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
