    // tight fits even more aggressively to minimize the final bin count.
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for opening a new bin: if bin_residual == bin_capacity, we are evaluating a new bin.
    // We scale this penalty by the progress to be more conservative as the stream nears the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (1.0 - progress) * 45.0 + 15.0 
    } else { 
        0.0 
    };

    // Calculate how well the next item would fit into the remaining space
    // If next_item_size is 0, we treat it as neutral.
    let next_fit_score = if next_item_size > 0 && post_residual >= next_item_size {
        // High reward for leaving space that perfectly accommodates the next item
        -15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64)
    } else if next_item_size > 0 {
        // Penalty for creating a "dead zone" that cannot fit the next item
        10.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Non-linear coupling: Favor smaller post_residuals (Best Fit), but soften this
    // preference when the bin is nearly empty to avoid fragmenting the space.
    // We use a quadratic term to heavily penalize "almost empty" bins (large post_residual).
    let fit_efficiency = (post * post) / (bin_capacity as f64 * 1.5);

    // Interaction with global state: penalize creating too many bins early on
    let density_pressure = (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // Final score: minimize this value
    // Lower post_residual is good, but mitigated by next_fit_score and new_bin_penalty
    fit_efficiency + new_bin_penalty + next_fit_score + density_pressure
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

