    // to keep the bin occupancy balanced, preventing outliers.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. Scarcity/Opening Logic:
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // reward it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Heuristic:
    // When evaluating a brand-new bin (bin_residual == bin_capacity),
    // we only return a low score if the item is large or the system is highly fragmented.
    if bin_residual == bin_capacity {
