    // Base cost is the remaining space (Best-Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (very small residual) that is unlikely to fit future items.
    // We penalize residuals below 10, weighted by how far we are into the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (2.0 + 3.0 * progress);
    }

    // If this is a new bin, apply a heavy penalty that decreases as the stream progresses.
    // This forces the algorithm to utilize existing bins early on, then be more flexible later.
    if is_new_bin {
        score += 25.0 * (1.0 - progress).powf(1.5);
    }

    // Lookahead logic: if we know the next item, reward bins that can accommodate it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalty for "wasting" a bin if we have plenty of open bins available.
    // This discourages opening new bins when many are already active.
    if is_new_bin {
        score += (open_bins_count as f64).powf(0.8) * 5.0;
    }

    // Reward bins that bring the residual closer to the global mean, 
    // encouraging a balanced filling across all active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals < 10 are often unusable for the given range 10-80)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of potential future items
    // If the post_residual is a multiple of the next_item_size, we favor this placement.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        score += (remainder as f64) * 0.5;
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // existing bins could have taken the item. We only want to open a new bin if the
    // existing fits are truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        score += 20.0; 
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64);
        }
    }

    // 4. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean residual of open bins
    // to keep the bin pack "tight" and uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression weighting:
    // As we approach the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small gaps that cannot fit common items.
    // We prioritize bins that leave a post_residual of 0 (perfect fit).
    // If post_residual > 0, we penalize it based on whether it falls into the "death zone" (1..10).

    let mut score = post_residual as f64;

    // Penalty for creating a small, unusable gap (1-9).
    // Gaps between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: If we are nearing the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // Lookahead logic: If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless there are no other good fits available.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;

        // Dynamic penalty: If many bins are already open, opening a new one is more expensive.
        score += (open_bins_count as f64) * 1.5;
    } else {
        // Reward bins that are "tightening" (getting closer to the mean).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // If this is the only bin that can fit the item, we are forced to take it.
    // Lower the score to ensure it is chosen over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

