    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly 0 space for the next item (perfect fit).
        score -= (100.0 - gap_after_next) * 0.8;
    }

    // 3. Fragmentation Control: Penalize bins that deviate significantly from the mean_residual.
    // We want to keep all bins at a similar level of fullness to maximize future packing options.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.3;

