    } else {
        // If it's an existing bin and it's the last chance (fitting_bins_count == 1), 
        // aggressively prefer it to avoid the cost of a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progress Normalization: As the stream nears the end, be more conservative with space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
