    // 3. Penalty for opening new bins: Only open a new bin if the fit is truly poor.
    if bin_residual == bin_capacity {
        // We only want to open a new bin if the existing bins are all "bad" fits.
        // If there are many fitting bins, opening a new one is highly discouraged.
        score += (fitting_bins_count as f64) * 50.0;

        // As the stream progresses, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current average residual.
    // This keeps the "tightness" of all bins consistent.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to how many bins are already open
        // and how easily the current item could have fit elsewhere.
        score = 25.0 + (open_bins_count as f64 * 0.5);
        if fitting_bins_count > 0 {
            score += 50.0 * (1.0 - progress);
