        }

        // If this is the last fitting bin, prioritize it to avoid creating a new one
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Final non-linear dampening based on total open bins to prevent excessive fragmentation
    score += (open_bins_count as f64).powf(1.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. 
