    let capacity = bin_capacity as f64;

    // Base score is the post-placement residual (Best Fit principle).
    // Penalize small residuals that create "orphaned" space (dead space < 10).
    let mut score = if post < 10.0 && post > 0.0 {
        post + 20.0 
    } else {
        post
    };

    // Interaction term: If we are near the end of the stream, prioritize tighter packing
    // by penalizing empty space more heavily as progress increases.
    score += (progress * 50.0) * (post / capacity);

    // Lookahead coupling: If next_item_size is large and we don't have space,
    // penalize the current bin if it leaves a residual that is too small for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
