    // If this is a new bin, apply a threshold penalty to discourage opening new bins unless necessary
    if bin_residual == bin_capacity {
        // Penalty scales with the number of open bins to prevent fragmentation
        // and checks if we have any other options (fitting_bins_count > 0)
        score += 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Lookahead heuristic: penalize placements that make it hard to fit the next item
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // If next item cannot fit, add a penalty based on how 'wasted' the remaining space is
                score += 15.0 + (post_residual as f64 * 0.2);
            } else {
                // If next item can fit, reward this bin for creating a better fit for it
                score -= (bin_capacity - next_item_size) as f64 * 0.1;
            }
        }
    }

    // Progression awareness: be more conservative with new bins as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    // Penalize bins that deviate too far from the global mean residual (load balancing)
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.15;

    // If this bin is the last chance to fit the item, give it a slight preference boost
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
