    // We penalize small residues that are too small to fit common future items.
    // As progress increases, we become more aggressive in packing tightly.
    let mut score = post;

    // Penalty for "Dead Space": if post_residual is > 0 but < minimum item size (10),
    // it is statistically likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: If next_item_size exists, penalize bins that cannot fit it
    // after the current placement.
    if next_item_size > 0 {
