    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 / (1.0 + diff));
    }

    // 3. Penalty for "Wasted Potential": If we create a residual that is too small to fit any 
    // likely future items (e.g., < 10, assuming minimum item size is 10), penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // 4. Heuristic for New Bin (bin_residual == bin_capacity):
    // Only open a new bin if the current open bins result in very poor fit distributions.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless existing bins are extremely crowded or poorly matched.
        score += 40.0 + (mean_residual * 0.5);
    }

    // 5. Fitting constraint: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
