pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-20 range)
    // If post_residual is small but > 0, it creates "fragmentation" that is hard to fill.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 - (post_residual as f64 * 3.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins heavily unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Density: If this is the only bin that can fit the current item, 
    // it is a "Must Take" to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean Residual Balancing: Favor bins that stay close to the mean to avoid extreme outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize keeping the residual as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, 
    // heavily reward this bin. This effectively creates "Best-Fit-Pair" behavior.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if it creates a perfect or near-perfect fill
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless no other bin can fit the item or the mean residual is very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing bin works
            score += 65.0; 
        } else {
            // If no existing bin fits, normalize the cost of opening a new one
            score -= 10.0;
        }
    }

    // 4. Global Density Calibration:
    // If the mean residual of current bins is high, we are being too wasteful.
    // Tighten the requirements for new bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    if mean_residual > 20.0 {
        score += mean_residual * progress;
    }

    // 5. Last-Chance Logic:
    // If this is the only bin that can fit the item, prioritize it to prevent
    // unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (1-5 units)
    // which are rarely fillable by future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item fits into this post_residual, reward this bin.
    // This is a "Best-Fit with Lookahead" incentive.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Global Bin Management: Penalize creating a new bin unless existing bins are near capacity.
    // If bin_residual == bin_capacity, we are evaluating a brand-new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average space in existing bins is already very tight (< 15)
            // or if we are nearing the end of the stream.
            let urgency = if mean_residual < 15.0 || progress > 0.95 { 0.0 } else { 100.0 };
            score += urgency;
        }
    } else {
        // 4. Scarcity Logic: If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }

        // 5. Density Balancing: If we have many open bins, penalize bins that increase the mean residual.
        if open_bins_count > 5 && post_residual as f64 > mean_residual {
            score += 20.0 * (post_residual as f64 / mean_residual);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large empty spaces (Best Fit logic)
    let mut score = post * post * 0.01;

    // Favor bins that leave just enough space for the next item (Lookahead optimization)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dynamic pressure: As we approach the end of the stream, prioritize packing density
    // over keeping extra bins open.
    let density_weight = 1.0 + (progress * 2.0);
    score += (mean_residual * density_weight);

    // If this is a new bin, apply a threshold penalty based on how many 
    // bins are already open and the progress of the stream.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is higher when many bins are already open
        // or when we are early in the stream.
        score += (open_bins_count as f64 * 5.0) * (1.0 - progress * 0.5);
    } else {
        // Reward bins that have a tight fit (low post_residual)
        // especially when fitting_bins_count is low (last chance).
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (already in 'score')

    // 2. Harmonic Penalty: Penalize gaps that are unusable for common item sizes.
    // Gaps in the range [1, 9] are effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Synergy: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Harmonic Fragmentation Control:
    // If we have many open bins, penalize opening a new one unless it's a perfect fit.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0; 
            // If the item perfectly fills the new bin, override the penalty.
            if post_residual == 0 {
                score -= 45.0;
            }
        }
    }

    // 5. Mean residual equilibrium: 
    // If this placement brings the bin closer to the global mean residual, reward it.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    // 6. Near-capacity thresholding: 
    // Reward filling a bin to within 5 units of capacity (Very high density).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // 7. Scarcity adjustment: 
    // As the stream progresses, become more aggressive (lower scores) to force tight fits.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-25).
    // If post_residual is in [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Coupling: If the next item is large, prioritize bins that can accommodate it.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 20.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins if we have many already open.
    // This forces the algorithm to consolidate items into existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Fitting Density: If this is the last chance for the current item, lower the penalty.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Mean Residual Alignment: Reward bins that keep us close to the global average residual.
    // This helps in keeping the distribution of space usage uniform across bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 6. Progression scaling: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize the post_residual (Best Fit) but penalize creating "orphaned" space 
    // that cannot fit the lookahead item or is significantly worse than the current mean.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin: Only do it if we are desperate (few fitting bins)
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 150.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // If no bins fit, new bin is the only option; set a baseline
            score = 50.0;
        }
    } else {
        // 2. Lookahead optimization: If post_residual is smaller than next_item_size,
        // it creates a "dead zone". Penalize this heavily.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 40.0;
            } else {
                // Reward if the placement leaves exactly enough space for the next item
                // or leaves the bin perfectly balanced
                score -= (post_residual as f64 - next_item_size as f64).abs() * 0.2;
            }
        }

        // 3. Efficiency alignment: Penalize bins that deviate far from the mean_residual
        // to keep bin fill levels consistent (Best Fit vs First Fit hybrid)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // 4. Critical threshold: If this is the last chance for this item, prioritize it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Decreasing logic: Favor bins that leave the least space (lower post_residual).
    // The base score is already post_residual, so we refine it.

    // 2. Penalty for creating "dead space" (gaps < 10): 
    // If the post_residual is too small to fit the smallest possible items (assumed ~10), 
    // it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Lookahead integration:
    // If next_item_size fits in the current post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Global Density Awareness:
    // If the current bin's residual is significantly better than the global mean, 
    // discourage using it for very large items to keep it for future small ones.
    if (bin_residual as f64) > mean_residual && item_size > 60 {
        score += 10.0;
    }

    // 5. Threshold logic for new bins:
    // If this is the new-bin candidate (bin_residual == bin_capacity), 
    // penalize opening a new bin unless the current fitting options are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 5.0; // High priority to open if no other option
        } else {
            // Heavily penalize opening a new bin if other bins can fit the item
            score = 100.0 + (fitting_bins_count as f64 * 10.0);
        }
    }

    // 6. Progress adjustment:
    // As we approach the end of the stream, prioritize closing bins (lower scores for tighter fits).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement
    let mut score = post_res;

    // Penalty for creating "slivers" (small, unusable gaps). 
    // We penalize values between 1 and 9 heavily, as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item fits in the current post_residual, 
    // favor this bin by reducing the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - (post_res / bin_capacity as f64));
    }

    // Dynamic adjustment based on stream progress: 
    // Early on, we are aggressive about packing tight. 
    // Near the end, we prioritize closing bins to reduce the total count.
    let tightness_factor = (mean_residual / bin_capacity as f64) * (1.0 - progress);
    score += tightness_factor * 10.0;

    // If this is the only bin that fits, prioritize it unless it's a terrible fit.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 40.0;
    }

    // New bin candidate logic:
    // If bin_residual == bin_capacity, this is a new bin.
    // We only want to open a new bin if the existing bins are "too full" to be efficient
    // or if we are nearing the end of the stream and need to consolidate.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open the first bin
        } else {
            // Penalize opening new bins based on how much space is left in current bins
            score += (mean_residual * 0.5) + (progress * 30.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual
    // We penalize larger post_residuals to encourage tight packing.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: penalize remainders that are "useless" (too small to fit common items)
    // Small residuals (1-9) are often "dead space" because min item size is likely > 0.
    // If post_residual is < 10, we heavily penalize it unless it is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 3. Lookahead integration: Try to keep space for the next item
    // If we have a next item, check if the current bin can accommodate it after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy)
            score -= 30.0;
        } else {
            // Penalize bins that would force a new bin for the next item if better options exist
            score += 15.0;
        }
    }

    // 4. Global State Awareness:
    // If this is the only bin that fits, we are forced to take it (low score).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New Bin Thresholding:
    // Only open a new bin if the current post_residual of existing bins would be very poor
    // or if the mean residual of current bins suggests we are fragmenting space.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the average residual is already quite low
        // or if we are at the very beginning of the stream.
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 100.0; // Discourage new bins if we have plenty of space
        } else {
            score += 40.0; // Base cost to open a new bin
        }
    }

    // 6. Progress Scaling:
    // As the stream progresses, prioritize tight packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual ranges that are likely to be unusable.
    // Gaps between 1 and 9 are extremely difficult to fill given the input distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item cannot fit in this bin, 
    // prioritize leaving space for it if the current fit is "tight".
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0; // Reward bins that can accommodate the next item
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the number of open bins is very low or no other bin fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Essential to open a new bin if nothing fits
        }
    }

    // 4. Tight Fit Bonus: Reward Best-Fit behavior (minimizing post_residual).
    // We already have post_residual in the score, but we add a non-linear scaling
    // to strongly favor filling bins near capacity.
    score += (post_residual as f64).powf(1.1);

    // 5. Mean Residual Balancing: Prevent fragmentation. 
    // Penalize bins that deviate significantly from the mean residual of the system.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead: reward bins where the post_residual can fit the next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "perfect" or near-perfect fit for the next item
            score -= (bin_capacity - post_residual) as f64 * 0.5;
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Penalize if this bin becomes unable to hold the next item while others might
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. New Bin logic: Only open a new bin if the current fit is very poor
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open new if we have very few open bins or the average space is already very low
        if open_bins_count > 0 && mean_residual > 15.0 {
            score += 50.0; // High penalty to avoid opening new bins prematurely
        }
    }

    // 4. Fitting constraints: If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Progression damping: As the stream nears the end, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

