pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res.powf(1.5);

    // Penalty for opening a new bin unnecessarily
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or if we have many open bins already,
        // otherwise, heavily penalize creating a new bin.
        score += (1.0 - progress) * 150.0;
        score += (open_bins_count as f64) * 5.0;
    }

    // Lookahead logic: If a next item exists, reward bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin because it 
    // forces the next item into a new bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res).sqrt() * 20.0;
        } else {
            // Reward bins that have "perfect" residual for the anticipated next item
            score -= (post_res - next_item_size as f64).abs().sqrt() * 5.0;
