        // Only open a new bin if we have many open bins already (to avoid fragmentation)
        // or if it's the only way to get a "clean" fit.
        score += (open_bins_count as f64) * 2.5;
    } else {
        // If this is an existing bin, favor it if it's the last chance (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
