        }
    }

    // 5. Progress-based pressure: As we approach the end of the stream, 
    // become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

