        if !fit_next {
            // Penalty for stranding the next item if we are mid-stream
            score += (next_item_size as f64) * 0.5;
        }
    }

    // Dynamic thresholding: As the stream progresses, become more conservative about opening new bins
    if is_new_bin {
        // Penalty for opening a new bin is weighted by how many existing bins could have taken the item
        // If fitting_bins_count > 0, we heavily penalize opening a new bin
        score += 45.0 + (fitting_bins_count as f64 * 25.0) + (progress * 20.0);
    } else {
        // Reward filling bins that are already below the global mean residual to consolidate space
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // Penalize filling bins that are significantly above the mean (keep them open for larger items)
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 10.0;
        }
    }

    // Interaction term: Coupling stream progress with the scarcity of fitting bins
    // Towards the end of the stream, prioritize clearing existing bins (lower score for filling them)
    score -= (progress * 10.0) / (fitting_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #216: Harmonic-Residual Coupling
    // Objectives:
    // 1. Prioritize "Best-Fit" by penalizing post_residual (Best-Fit Decreasing logic).
    // 2. Introduce harmonic thresholds: small post_residuals are "dangerous" if they create unusable gaps.
    // 3. Lookahead integration: incentivize creating a bin state that perfectly accommodates the next item.

    let mut score = post_residual as f64;

    // Penalty for creating a bin that is almost empty (fragmentation)
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless there are no other options
        score += 45.0;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Harmonic Penalty: If post_residual is small but > 0, it creates "unusable" space.
    // We penalize values that aren't multiples of common item sizes (e.g., 20, 25).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Lookahead Coupling: If next_item_size can fit exactly into post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        // Reward perfect fit for the next item
        if fit_diff == 0.0 {
            score -= 25.0;
        } else if fit_diff < 10.0 {
            score -= 10.0;
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower mean_residual)
    // If this bin's post_residual is lower than the global mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Scale by relative progression to tighten constraints near the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

