    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle).
    // Penalize large gaps that are likely to become "dead space".
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: 
    // If post_residual is a multiple of next_item_size, it's a high-probability fit.
    // We reward bins that leave a residual specifically accommodating the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 45.0;
        } else if post_residual < next_item_size {
            score += 20.0; // Penalty for stranding the next item
        }
    }

    // 3. Fragmentation Control:
    // If we have very few fitting bins, we should be more conservative about opening new ones.
    // If this is the only bin that fits (fitting_bins_count == 1), heavily reward using it
    // to avoid the cost of a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    // Only open if the current mean_residual is very low (implying we are already packing tightly).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            // If existing bins are mostly empty, don't open a new one.
            score += 100.0;
        } else {
            // Otherwise, keep the cost stable to allow opening when necessary.
            score += 40.0;
        }
    }

    // 5. Lookahead efficiency:
    // If the current placement leaves a residual too small for any likely item (e.g. < 10),
    // and we are early in the stream, penalize it to keep bins "flexible".
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (1.0 - (step_index as f64 / total_items as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common minimums (10)
    // but large enough to be wasted. If post_residual is in (0, 10), it's highly likely to be dead space.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead Integration: If the next item can fit in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bins Pressure: Penalize opening new bins heavily unless necessary.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have very few open bins or if no other bin is a "good" fit.
        score += (open_bins_count as f64) * 5.0;

        // If there are bins that could fit this item, penalize the new bin creation significantly.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Reward filling existing bins to keep count low.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // 4. Distributional Awareness: Use mean_residual to avoid fragmenting bins differently than the current average.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // We heavily penalize residuals that are smaller than 10, as they are likely useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly in the new post_residual,
    // reward this bin choice to consolidate space.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // Bonus for creating a bin that perfectly matches the next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // 3. Pressure to fill bins: If we have many open bins, prioritize filling existing ones
    // over opening new ones. If this is a new bin (bin_residual == bin_capacity),
    // penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);
        // Only open a new bin if the fitting options are truly terrible
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Balance: Reward keeping the bin residual close to the current mean_residual
    // to keep the bin distribution uniform.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    // 5. Final constraint: If this is the only bin that fits, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. Lower is better.
    // We aim to balance Best-Fit (minimizing post_residual) with lookahead awareness and bin density management.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: Penalty for leaving large gaps (Best-Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "orphan" space (dead space < 10, as items are >= 10).
    // If post_residual is < 10, it is effectively unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Global Density Management: Penalize creating new bins unless necessary.
    if is_new_bin {
        // If we have fitting bins, opening a new one is expensive unless the mean residual is very high.
        if fitting_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        } else {
            // If no other bins fit, opening a new one is mandatory; normalize the score.
            score -= 10.0;
        }
    }

    // 5. Dynamic Time Horizon: Be more conservative (tighter packing) as we near the end of the stream.
    if progress > 0.8 {
        // Near the end, punish large residuals more heavily to clean up.
        score += post_residual as f64 * 0.5;
    }

    // 6. Penalty for creating too many open bins (fragmentation).
    score += (open_bins_count as f64).powf(1.2) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals) that are unlikely to fit future items.
    // We increase penalty as the stream progresses, forcing tighter packing later.
    let dead_zone_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * (1.0 + progress * 5.0)
    } else {
        0.0
    };
    score += dead_zone_penalty;

    // Lookahead coupling: if the next item is large, avoid leaving small gaps.
    if next_item_size > 0 {
        let gap_mismatch = (post as i32 - next_item_size as i32).abs() as f64;
        score += gap_mismatch * 0.5 * (1.0 - progress);
    }

    // New Bin Logic: Discourage opening new bins unless the current fit is extremely poor.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the open bins are already very full (high mean_residual is low).
        // If mean_residual is small, all bins are tight, so opening a new one is better than fragmenting.
        score = 40.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // Favor bins that align with the mean state of the system to keep residuals uniform.
        let deviation_from_mean = (post - mean_residual).abs();
        score += deviation_from_mean * 0.2;

        // Penalize the "last chance" bin to encourage aggressive filling if we are near the end.
        if fitting_bins_count == 1 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // 2. Penalty for creating "dead space": residuals < 10 are often hard to fill.
    // If post_residual is in (0, 10), it's a "fragmentation trap".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic: if next_item fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple of 
    // common item sizes (e.g., 20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 5. If this is the only bin that can fit the item, we are forced to use it.
    // But if it creates a tiny fragment, we might prefer opening a new bin.
    if fitting_bins_count == 1 && post_residual < 5 {
        score += 30.0;
    }

    // 6. Manage total open bins: penalize opening a new bin unless the current 
    // best-fit options are significantly suboptimal.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Only pick if fitting bins are scarce or highly fragmented.
        score = 60.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Dampen score based on how much this bin deviates from the mean fill
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 7. Progression scaling: as we near the end of the stream, prioritize 
    // closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
