pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (the "fragmentation" trap).
    // If post_residual is small but > 0, it's often better to have it larger 
    // or zero. We penalize gaps in the (0, 15) range.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 - (post_residual as f64);
    }

    // 2. Aggressive 2-step lookahead: 
    // If we can perfectly fit the next item into the current residual, prioritize this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave just enough space for the lookahead item.
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Penalize if the next item won't fit in this bin, but it could have fit 
            // in a different open bin.
            score += 10.0;
        }
    }

    // 3. Balance usage: avoid opening new bins unless necessary (fitting_bins_count == 0).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no other bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0; // Accept opening a new bin if it's the only option.
        }
    }

    // 4. Global state awareness:
    // If we are late in the stream, be more aggressive about filling bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    // 5. Mean residual alignment:
    // Penalize bins that deviate significantly from the average fullness, 
    // to keep the bin landscape uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
