pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left: lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger items from fitting. We penalize small residuals more 
    // heavily as we approach the end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * (1.0 + progress);
    }

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it.
    // If the current post_residual is smaller than the next_item_size, we penalize this bin.
    if next_item_size > 0 && (post_residual < next_item_size) {
        score += (next_item_size as f64 - post_res) * 0.5;
    }

    // New Bin Penalty: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the existing fits are statistically poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already tight (< 15)
