        if fitting_bins_count > 0 && mean_residual > 15.0 {
            score += 50.0;
        } else {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Favor bins that align the post_residual closer to the mean_residual of the open bins
    // to keep the bin fill-levels homogeneous.
    score += (post_res - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
