    // However, we apply a non-linear weight to prevent creating "orphaned" small gaps.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we heavily reward this bin to create a "perfect pair" (Best-Fit-Decreasing logic).
    if next_item_size > 0 && next_item_size <= post_residual {
