pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only do it if the fit is extremely poor in all existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are early in the stream or if existing bins are very full.
        // If fitting_bins_count > 0, we heavily penalize opening a new bin.
        score += (fitting_bins_count as f64 * 150.0) + (progress * 50.0);
    } else {
        // Heuristic: Prefer bins where the post_residual is small (tight packing).
        // If post_residual is very small (near 0), it's excellent.
        // If post_residual is large, we check if it can accommodate the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward bins that can accommodate the next item (Lookahead optimization)
                score -= (next_item_size as f64) * 0.8;
            } else {
                // Penalize creating a bin that cannot fit the next item if it's large.
                score += (next_item_size as f64) * 0.4;
            }
        }

        // Penalty for creating 'dead space' (bins that are hard to fill later).
        // If post_residual is between 1 and 9, it's often unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Global state correction: balance the load across open bins.
        // If this bin's residual is significantly higher than the mean, prefer filling it.
        if (bin_residual as f64) > mean_residual {
            score -= 10.0;
        }

        // If this is the last chance for this item (fitting_bins_count == 1), 
        // we must take it unless it is extremely inefficient.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left: lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead zones": if the post_residual is small but not zero,
    // it is often harder to fill than a slightly larger residual.
    // We apply a non-linear penalty to residuals in the (0, 15) range.
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res).powf(1.5);
    }

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it.
    // If the current bin's post_residual is too small for the next item, penalize it
    // proportionally to the progress (as the stream nears the end, we care less about lookahead).
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += (1.0 - progress) * 25.0;
    }

    // Dynamic pressure: as open_bins_count increases, penalize opening new bins 
    // by making existing bins more attractive (lowering their score).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty increases significantly if there are existing fitting bins.
        score += (fitting_bins_count as f64 * 40.0) + (open_bins_count as f64 * 5.0);
    } else {
        // Existing bin bonus: incentivize filling existing bins to reduce fragmentation.
        score -= (1.0 - (post_res / bin_capacity as f64)) * 10.0;

        // If this bin's residual is close to the mean, it's a "good" candidate for balancing.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to discourage opening new bins
    // unless the current open bins offer very poor fits (Best Fit Decreasing logic).
    if bin_residual == bin_capacity {
        score += 25.0; 
    }

    // 2. Harmonic Class Logic: Penalize post_residual based on its "usability" for common item sizes.
    // We prioritize keeping the residual as a multiple of common item sizes (e.g., 20, 25, 33).
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5 
                         + (post_residual % 25) as f64 * 0.3;
    score += harmonic_penalty;

    // 3. Lookahead coupling: If next_item_size is large, favor bins that leave enough space
    // for that specific item. If next_item_size fits in post_residual, reduce score.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward binning that accommodates the next item
        } else {
            // If next_item_size is large and won't fit, penalize small slivers of remaining space
            if post_residual < 15 && post_residual > 0 {
                score += 10.0;
            }
        }
    }

    // 4. Global state pressure: If we have many open bins, we become more aggressive
    // about filling existing bins, even if it creates slightly suboptimal residuals.
    let fill_pressure = (open_bins_count as f64 / (total_items as f64 / 10.0 + 1.0)).min(1.0);
    score -= fill_pressure * 10.0;

    // 5. Fitting count logic: If this is the only bin that fits the current item, 
    // significantly reduce its score to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean residual balance: Favor bins that stay near the global mean residual
    // to maintain a uniform packing density.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
