    // 2. Lookahead Synergy: If the next item fits perfectly in this post_residual, 
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Slight reward if the bin can accommodate the next item, 
            // but penalize if it leaves too much wasted space.
            score -= 20.0;
        }
    }

    // 3. Fragmentation Control: Penalize residuals that are too small to fit 
    // typical items (e.g., < 10) unless it's a perfect fill (0).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Mean Residual Balancing: If this bin's residual is significantly 
    // worse than the average, discourage using it further.
    if (post_residual as f64) > mean_residual {
        score += 15.0;
    }

    // 5. New Bin Thresholding: If this is an empty bin (new bin candidate),
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 85.0;
        // If we have very few open bins, we are more willing to open a new one
        // to avoid fragmentation later.
        if open_bins_count < 2 {
            score -= 10.0;
        }
    }

    // 6. Final scaling based on progress to encourage tighter packing in later stages.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic: 
    // 1. Prioritize Best-Fit (post_residual -> 0).
    // 2. Penalize fragmentation (small post_residual < 10) unless it's a perfect fit.
    // 3. Utilize lookahead: if next_item_size fits in post_residual, reward that bin.
    // 4. Dynamic thresholding: as we reach the end of the stream, prioritize closing bins.

    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (tiny residual that can't fit most items)
    // Small residuals like 1..9 are often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: If the next item fits in the remaining space, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Heuristic for opening new bins:
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing fitting bins are "too full" or "too empty" 
        // to accommodate the current item efficiently, or if we have very few open bins.
        if open_bins_count > 0 {
            score += 30.0; // Base penalty for opening a new bin

            // If we are nearing the end of the stream, discourage opening new bins.
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
    } else {
        // If we are evaluating an existing bin, check the fitting_bins_count.
        // If it's the only bin that fits (fitting_bins_count == 1), 
        // give it a slight bonus to force consolidation.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Balance the mean residual: 
    // If the average bin is getting too empty, prioritize filling existing bins.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

