    // Penalize small residuals that are likely to become "dead space" (< 10).
    let mut score = post_res;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead influence: If the next item fits into the current post_residual, 
    // reward this bin to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - (post_res / bin_capacity as f64));
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower open_bins_count).
    // If this is the last fitting bin, slightly reward using it to prevent opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is a new bin candidate.
    // Apply a cost that scales with the progress to discourage opening new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 + (25.0 * progress);
    }

    // Global balance: Penalty for deviating from the mean_residual of other bins.
    // This helps keep the bin fillings somewhat uniform.
    let dev = (post_res - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

