    // 3. Last-Chance Mitigation: If this is the only bin that fits the current item,
    // we must take it regardless of fit quality to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // 4. Global Density Balance: If the current bin's residual is significantly better 
    // than the global mean, prioritize filling it to keep the average residual low.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin Aversion: Heavily penalize opening a new bin unless the fit in 
