}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual.
    // However, we penalize very small residuals (e.g., 1-4) that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, prioritize leaving space for it.
    // If post_residual is smaller than the next item, we create an "orphaned" space.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            // Penalize creating a hole that cannot fit the smallest possible item (10).
            score += 15.0;
        }
        // Reward keeping space for the next item if it fits perfectly.
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Harmonic Bin Partitioning:
    // Prefer filling bins to specific thresholds (e.g., 1/2, 1/3, 1/4 of capacity) 
    // to improve the probability of packing future items of common sizes.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let harmonic_penalty = ((fill_ratio * 4.0).sin().abs()) * 10.0;
    score += harmonic_penalty;

    // 4. New Bin Thresholding:
    // Only open a new bin if the current fit is extremely poor (post_residual is very large) 
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open new bin
        } else {
            // Discourage opening new bins unless the existing fit is truly terrible (> 60% waste)
            score = 60.0; 
        }
    }

    // 5. Global State Awareness:
    // As the stream progresses, tighten the requirement to open new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., < 10), it is likely to be unusable.
    // We penalize these "sliver" gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Best-Fit Bias: Encourage filling bins tightly.
    // We reward placements that bring the bin residual closer to the mean_residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, 
