    }

    // 2. Lookahead Coupling: If next_item_size is large, avoid bins that leave 
    // insufficient room for it, effectively shifting toward Best-Fit-Decreasing logic.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that leave exactly enough room for the next item (synergy)
            if (post_residual as i32 - next_item_size as i32).abs() < 5 {
