    // 3. Global State Balancing: Prevent fragmentation by penalizing the creation of a new bin
    // unless the current open bins are already too "tight" (low mean_residual).
    if bin_residual == bin_capacity {
        // New bin penalty: scale with progress to allow more bins early, restrict late.
        let new_bin_penalty = 30.0 + (progress * 40.0) + (mean_residual * 0.5);
        score += new_bin_penalty;
    } else {
        // Encourage filling existing bins if they are relatively empty, 
        // effectively implementing a "Worst-Fit" bias when bins are very empty to keep
        // them open for future large items.
        if bin_residual > 60 {
            score -= 10.0 * (bin_residual as f64 / 100.0);
        }
    }

    // 4. Critical Thresholding: If this is the only bin that fits, prioritize it 
    // heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow more flexibility as the stream ends.
    // The "new bin" candidate has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As progress increases, the cost of opening a new bin decreases to allow finishing
        // remaining items efficiently.
        50.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Best Fit Decreasing logic: Favor bins that leave very little space (low post_residual).
    // Use quadratic penalty for large residual gaps to avoid "dead space".
    let mut score = post * post / bin_capacity as f64;

    // Lookahead interaction: If the next item can fit in the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - (next_item_size as f64 / post));
    }

    // If this is the only bin that can fit the item, reward it to prevent opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Influence of mean_residual: If current bin is significantly worse than average, penalize.
    if !is_new_bin && (post as f64 > mean_residual) {
        score += (post as f64 - mean_residual) * 0.5;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

