    // (the "fragmentation trap"), especially when the next item is large.
    if post_residual > 0 {
        // Penalize residuals that cannot fit the next item if a next item exists
        if next_item_size > 0 && post_residual < next_item_size {
            score += 50.0 / (post_residual as f64 + 1.0);
        }

        // Harmonic classes: Favor residuals that are multiples of common item sizes (e.g., 20, 25)
        // to maximize the probability of filling the bin exactly later.
        let mod_val = post_residual % 20;
        if mod_val != 0 {
            score += 5.0 * (mod_val as f64 / 20.0);
        }
    }

    // 2. New Bin Threshold: If this is a new bin, apply a structural cost.
    // We only open a new bin if the current fit is extremely inefficient.
