        // to avoid stranding items.
        let progress = step_index as f64 / total_items as f64;
        score = 35.0 - (progress * 10.0);
    } else {
        // 3. Pressure logic: If only one bin fits, prioritize it strongly to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // 4. Mean Residual Balancing: If this bin is significantly emptier than the average,
        // it is a good candidate for "filling up" rather than leaving it as a sparse bin.
        if (bin_residual as f64) > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

