    // If bin_residual == bin_capacity, we are evaluating a brand new bin.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 25.0);

        // If we have many open bins already, make opening a new one very expensive
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Mean residual balancing: Prefer bins that stay close to the current average utilization
    // to keep the "wastage" distributed somewhat evenly.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Final adjustment: Strongly favor tight fits (Best Fit decreasing)
    // Reward bins that result in small post_residuals (high utilization)
    score += (post_residual as f64) * 0.5;

    score
