pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If the post_residual is less than 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly into this bin,
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Prefer bins that keep the mean residual stable.
    // If our post_residual is significantly lower than the mean, we are "tightening" the bin.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 4. If this is the only bin that can fit the item, we must be careful not to 
    // waste it if a better fit exists for the next item.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0;
    }

    // 5. Penalize opening a new bin unless the current fit is extremely poor.
    // If bin_residual == bin_capacity, it's a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (high density),
        // or if we have many bins open and should try to consolidate.
        if mean_residual > 30.0 || open_bins_count < 5 {
            score += 40.0;
        } else {
            score += 80.0;
        }
    }

    // 6. Progress-based scaling: Be more conservative (tighter packing) as the stream nears the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit strategy)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next item is large, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // Penalize bins that block the next item
        }
    }

    // If this is the last chance to fit the item in an existing bin, prioritize it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Global state awareness: if we have many bins open, be more aggressive with packing
    // If progress is high, prioritize closing bins (Best Fit)
    if open_bins_count > 0 {
        let utilization = 1.0 - (mean_residual / bin_capacity as f64);
        score += (utilization * 10.0) * progress;
    }

    // New bin penalty: only open a new bin if the fit is truly terrible
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if there is an existing option
            score += 60.0 + (progress * 20.0);
        } else {
            // No options left, make the new bin neutral
            score = 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: scales with progress to make it harder to open new bins late-game
    if is_new_bin {
        score += 25.0 + (progress * 45.0);
    } else {
        // Reward bins that are "tight" fits, but penalize creating "dead zones" (residuals < 10)
        // unless it's a perfect fit (post_residual == 0)
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; 
        } else if post_residual == 0 {
            score -= 5.0;
        }

        // Lookahead heuristic: if next_item_size is large, favor bins that can accommodate it 
        // by avoiding bins that become too small after this placement.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 12.0 * (1.0 - progress);
            }
        }
    }

    // Dynamic pressure: if many bins are open, prioritize consolidation
    score += (open_bins_count as f64 * 0.5) * (1.0 - progress);

    // Interaction with mean_residual: avoid outliers that deviate from the mean efficiency
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
