    // Harmonic/Modulo logic: Favor bins that leave residuals which are multiples 
    // of common item sizes (e.g., 25, 33, 50).
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // Penalty for opening a new bin unnecessarily:
    // If we are opening a new bin (bin_residual == bin_capacity), 
    // apply a cost based on the total number of bins already opened.
    if bin_residual == bin_capacity {
