pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left: we prefer tight fits (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If the post_residual is < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is large, we want to save space in this bin.
    // If next_item_size is small, we are less concerned about tight packing here.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post_res).max(0.0) * 0.5;
        score += lookahead_penalty;
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize closing bins
    // by heavily penalizing new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress to force consolidation.
        score += 40.0 * (1.0 + progress * 2.0);

        // If we have many open bins already, make opening a new one even more expensive.
        score += open_bins_count as f64 * 5.0;
    }

    // If this is the last chance to fit the item in an existing bin, reduce the score
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Coupling with mean_residual: penalize deviations from the average to keep bins uniform.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype #401: Harmonic Classes & Residual Conservation
    // Logic: Penalize fragmentation (post_residual) using non-linear harmonic scaling.
    // Reward bins that can accommodate the next item (lookahead coupling).

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize small "sliver" residuals that are difficult to fill later
    // Small residuals (1..10) are extremely toxic in 1D bin packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the post-placement bin, lower the score.
    // This encourages "Best-Fit" clustering for known future items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless the current options are very poor.
    // If we are choosing a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the number of existing open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Density Balancing: If the bin is becoming very empty compared to the mean, 
    // discourage using it further to keep high-density bins available.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. Last Chance Logic: If this is the only bin that fits the current item, 
    // reduce the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress Scaling: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize the tail-end bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
