    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Encourage filling bins that are already "half-empty" to keep the mean_residual low.
    // If post_residual is close to the mean_residual, reward the fit.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
