    let mut score = post_residual as f64;

    // 2. Penalize opening a new bin heavily unless necessary.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0; // Penalty for opening a new bin when others exist
        }
        return score;
    }

    // 3. Perfect Fit Bonus: If post_residual is 0, strongly favor this bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 4. Lookahead Logic: If the next item fits perfectly into this post_residual,
    // we want to prioritize this bin even if it isn't the tightest current fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // If the next item fills the bin perfectly, reward it.
        if diff == 0.0 {
            score -= 30.0;
        } else {
            // Otherwise, favor bins that leave just enough for the next item.
            score -= 15.0 / (diff + 1.0);
        }
    }

    // 5. Global state normalization:
    // If we are nearing the end of the stream, prioritize closing bins (lower mean_residual).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
