            0.0
        };
        score += fit_penalty;
    }

    // Dynamic thresholding based on stream progress:
    // As the stream nears the end, become more aggressive about filling existing bins
    // to avoid leaving too many half-empty bins open.
    let exhaustion_factor = (1.0 - progress) * open_bins_count as f64;
    score += exhaustion_factor * (post / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it.
    // Only open a new bin if the current fit is significantly worse than the average residual.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other bins can fit the item.
        let new_bin_base_cost = 45.0;
        score = new_bin_base_cost + (mean_residual * 0.5);

        // If we are at the end of the stream, increase the cost to force packing into existing bins.
        score += progress * 20.0;
    }

    score
}

