    // If this is the last fitting bin, we are forced to use it or open a new one.
    // If the post_residual is terrible, we might prefer opening a new bin instead.
    if fitting_bins_count == 1 && !is_new_bin {
        if post_residual > 20 {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // Global state awareness: if many bins are open, try to pack tighter by penalizing 
    // empty space more heavily.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Favor bins that align with the current mean residual to keep bins balanced
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as we approach the end of the stream
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (40.0 * (1.0 + progress.powf(2.0))) + (open_bins_count as f64 * 0.5) 
    } else { 
        0.0 
    };

    // Calculate "tightness": preference for smaller post_residuals (Best Fit)
    // Non-linear scaling: square the post_residual to heavily penalize large gaps
    let tightness_score = post.powf(1.6);

    // Lookahead coupling: if the next item is large, penalize small residuals that would strand it
    // If next_item_size is 0 (end of stream), this term vanishes
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Diversity control: penalize opening new bins if there are existing bins that fit
    let fragmentation_penalty = if fitting_bins_count > 0 && is_new_bin {
        100.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Interaction term: prioritize bins with residuals close to the mean to maintain uniform bin states
    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    tightness_score + new_bin_penalty + lookahead_penalty + fragmentation_penalty + deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (1-9)
    // which are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Logic: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, this bin is "blocked" for the next step.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that have exactly enough space for the next item (synergy).
            if post_residual == next_item_size {
                score -= 15.0;
            }
        }
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless the current best fit 
    // is extremely poor (leaving a large, unusable fragment).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full)
        // or if we have very few open bins currently.
        score += 40.0 + (mean_residual * 0.5);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Harmonic Scaling: Penalize configurations that result in "harmonic" waste
    // by checking against bin_capacity fractions.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.8 {
        score -= 10.0; // Reward high-density bins
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize 
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
