    // 4. Balance global load: Avoid opening new bins unless absolutely necessary
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the current mean_residual is already very tight
            if mean_residual > 20.0 {
