        // Encourage filling bins that are already partially full (below the mean)
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // 5. Progress-aware scaling: As we reach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

