        score += 50.0;
    }

    // 3. Lookahead Synergy: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // we must prioritize it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current 
    // options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only consider a new bin if the average residual is already quite low,
        // or if we are early in the stream.
        score += 35.0 + (mean_residual * 0.5);
    }

    // 6. Distribution Smoothing: Use mean_residual to avoid fragmentation.
    // If this bin's post_residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize post_residual values between 1 and 9 (the smallest possible item size is 1).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is too small for next_item_size, we penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open bins pressure: penalize opening new bins unless necessary (fitting_bins_count == 0).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost based on open_bins_count.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if an existing one is available.
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If we must open a new bin, neutralize the penalty.
            score = 10.0;
        }
    } else {
        // Favor bins that align with the mean residual to keep bin states uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Progression scaling: be more aggressive about space utilization as we approach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit (minimize post_residual)
    // The base score is already post_residual, which inherently favors tightest fit.

    // 2. Lookahead Synergy: If post_residual can accommodate the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        // We reward bins that leave exactly enough for the next item (perfect fit)
        // or bins that leave enough space to keep the next item flexible.
        score -= (bin_capacity - post_residual) as f64 * 0.5;
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Penalty for "New Bin" creation if other bins are available
    // If we are considering a new bin (bin_residual == bin_capacity) but others fit,
    // penalize this choice heavily based on how many bins are currently open.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 + (open_bins_count as f64 * 5.0);
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from the average.
    // If post_residual is much smaller than the mean, it's a "tight" bin, which is good.
    // If post_residual is much larger, it's a "loose" bin, which is bad.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // 5. Urgency: As we approach the end of the stream, prioritize minimizing open bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: penalize opening new bins even more.
        if bin_residual == bin_capacity {
            score += 200.0;
        }
    }

    // 6. Last Chance Heuristic: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits that leave little room
    // for future fragmentation.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Synergy: If the next item fits into the post-placement bin, lower the score.
    // This encourages "pairing" items to reduce the number of bins used.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global Efficiency: If the bin is a new bin (bin_residual == bin_capacity), 
    // penalize it based on how many bins are already open to discourage opening new bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 25.0;

        // If we have other options, make a new bin very expensive.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // 4. Fragmentation Control: If post_residual is small but > 0, it creates "dead space"
        // that is hard to fill. Penalize residuals that fall in the 1-9 range.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 5. Dynamic Time Horizon: As we near the end of the stream, prioritize closing bins
        // over perfect packing to avoid leaving too many bins partially full.
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 && post_residual < 20 {
            score -= (20 - post_residual) as f64 * 2.0;
        }
    }

    // 6. Mean Residual Balance: If this bin's post_residual is significantly worse than
    // the global average, penalize it to keep bins uniform.
    if (post_residual as f64) > mean_residual + 10.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin option (bin_residual == bin_capacity) increasingly as the stream progresses
    // to force packing into existing bins, unless the bin is nearly empty.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 25.0 + (progress * 50.0) } else { 0.0 };

    // Primary objective: Best-Fit Decreasing logic (minimize post_residual).
    // We use a non-linear penalty for small residuals (the "fragmentation trap").
    // If post_residual < 10, it's often better to save that space for smaller items,
    // so we apply a non-linear penalty for tiny gaps.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powf(2.5)
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large and this bin can't fit it,
    // we prefer a placement that leaves enough space for the next item if possible.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Global state awareness: If we have many open bins, penalize opening another one.
    let bin_count_penalty = (open_bins_count as f64).powf(1.2);

    // Final score: minimize this value.
    // We add post_residual to favor tight fits, but combine with penalties to avoid fragmentation.
    let mut score = post + fragmentation_penalty + new_bin_penalty + lookahead_penalty + bin_count_penalty;

    // Favor bins that align with the mean residual to keep bin states uniform.
    let mean_alignment = (post - mean_residual).abs() * 0.1;
    score += mean_alignment;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

