    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight packing.
    // 2. Lookahead Coupling: If post_residual is close to next_item_size, reward this bin 
    //    to create a perfect or near-perfect fit for the next arrival.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward configurations where the next item fits perfectly or near-perfectly
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Fragmentation Avoidance: If this is the last fitting bin, penalize leaving 
    //    a very small, unusable gap (e.g., < 10) unless the bin becomes exactly full.
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current mean 
    //    residual is already very tight, or if the current item is very large.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            score += 40.0;
        } else {
            score += 20.0;
        }
    }

    // 5. Global Efficiency: As the stream progresses, prioritize closing bins
    //    by rewarding placements that bring post_residual closer to 0.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best-Fit principle: minimize remaining space)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals below 10 are often hard to fill later.
    // If the post_residual is small but not zero, it's a "bad" fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize closing bins
    // by being more aggressive about fitting into existing space (Best-Fit)
    // and penalizing the creation of new bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we progress through the stream.
        score += 15.0 + (progress * 40.0);

        // If there are other bins that could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Global state awareness: If we have many open bins, prioritize bins with higher residuals
    // to consolidate space (Worst-Fit tendency for high-count scenarios to prevent fragmentation).
    if open_bins_count > 5 {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
    }

    // Final adjustment: penalize bins that deviate too far from the average residual
    // to keep the bin distribution uniform.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space; we penalize large gaps to maximize density (Best Fit).
    let mut score = post * post;

    // Penalty for creating a "fragmented" bin: if the post_residual is small but 
    // too large for most items (e.g., < 10), it becomes dead space.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(3);
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powf(1.5);
        }
    }

    // Dynamic thresholding: As the stream progresses, increase pressure to close bins.
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as total_items approaches.
    if bin_residual == bin_capacity {
        score += 250.0 * (1.0 + progress);
    }

    // Interaction with global state: penalize creating a new bin if we have many bins
    // with high residual space (mean_residual), to encourage consolidation.
    if bin_residual == bin_capacity {
        score += mean_residual * 2.0;
    }

    // Reward bins that have a tight fit (low post_residual) more strongly 
    // in the later stages of the stream to finish packing efficiently.
    score -= (1.0 - progress) * (bin_capacity as f64 - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize residual space exponentially to favor tightest fits.
    // Small post_residuals are favored.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Penalize residuals that cannot easily accommodate common item sizes.
    // If post_residual is small (e.g., < 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Density Balancing: If we are near the end of the stream, prioritize clearing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 20.0 * (1.0 - progress);
    }

    // 5. New Bin Logic: If this is an empty bin, add a dynamic penalty based on current capacity usage.
    // This prevents opening new bins unless the current bins are too fragmented.
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 6. Fragmentation Avoidance: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 7. Harmonic Modulo Bias: Favor residuals that are multiples of 10 or 25, 
    // as these are common divisors of the bin capacity 100.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit common items
    // (e.g., < 10) but not zero. This discourages creating "sliver" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current options are poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty proportional 
    // to the number of existing bins to force consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If there are bins that can already fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Mean Residual Balancing: Encourage filling bins that are already "fuller" than the average
    // to reduce the total number of active bins.
    if (bin_capacity - bin_residual) > (bin_capacity as f64 - mean_residual) as u32 {
        score -= 5.0;
    }

    // 5. Progress Normalization: As we approach the end of the stream, be more aggressive 
    // about fitting items into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight fits.
    // We weight this by the number of bins to prevent fragmentation in early stages.
    score += post_residual as f64 * (1.0 + (open_bins_count as f64 / 10.0));

    // 2. Lookahead Matching: If next_item_size fits in the post_residual, 
    // heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 5.5;
        // Further reward if the resulting residual is small (near-zero waste).
        let final_gap = post_residual - next_item_size;
        score -= (100.0 - final_gap as f64) * 0.5;
    }

    // 3. New Bin Thresholding: If this is a new bin, apply a structural penalty
    // that scales with the progress of the stream to encourage consolidation 
    // towards the end of the input stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Late in the stream, opening a new bin is very expensive.
        score += 80.0 * (1.0 + progress * 2.0);
    }

    // 4. Mean Residual Balancing: If the bin's current residual is significantly 
    // higher than the mean, prioritize using it to reduce overall variance.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 2.0;
    }

    // 5. Urgency: If fitting_bins_count is 1, this bin is the last chance for this item.
    // We make it highly attractive to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize near-empty bins
    // if a better fit is possible elsewhere.
    if fitting_bins_count > 1 {
        score += post_residual as f64 * 0.5;
    }

    // 2. Lookahead Integration: If the next item fits into the current bin's post_residual,
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global State Awareness: If we are late in the stream, be more aggressive
    // about filling existing bins to avoid opening new ones.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.8;
    }

    // 4. Dead Space Penalty: If the post_residual is too small to fit common items (e.g., < 10),
    // it's often worse than having a larger residual. Penalize this "dead space" creation.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 5. New Bin Logic: Discourage opening new bins unless the current options are very poor.
    if bin_residual == bin_capacity {
        // High baseline to prevent opening new bins unless all open bins are extremely inefficient.
        score = 45.0 + (open_bins_count as f64 * 0.1);

        // If we are early in the stream, be more conservative about opening new bins.
        if progress < 0.2 {
            score += 20.0;
        }
    }

    // 6. Mean Residual Balancing: If this bin is significantly emptier than the average,
    // favor filling it to bring it closer to the mean.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as the stream progresses to favor density
    let mut score = post_residual as f64;

    if is_new_bin {
        // A new bin is only desirable if we are early in the stream or the current fit 
        // options are exceptionally poor.
        score += (bin_capacity as f64) * (1.0 + progress.powi(2) * 5.0);
    } else {
        // Best Fit Decreasing logic: penalize large post_residuals (wasted space)
        // Coupling: As bins fill up, prioritize packing into bins that are already tight
        let waste_penalty = (post_residual as f64).powf(1.5);

        // Lookahead: If the next item is large, avoid leaving a residual that is just 
        // slightly too small for it (the "dead zone" problem).
        let mut lookahead_penalty = 0.0;
        if next_item_size > 0 {
            if post_residual < next_item_size && post_residual > 5 {
                lookahead_penalty = (next_item_size - post_residual) as f64 * 2.5;
            }
        }

        // Encourage using existing bins that have a residual close to the mean
        let mean_alignment = (post_residual as f64 - mean_residual).abs() * 0.5;

        score += waste_penalty + lookahead_penalty + mean_alignment;
    }

    // If this is the last fitting bin, grant a slight bonus to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "orphan" space that is too small for common item sizes
    // We penalize residuals that fall into the range (0, 15) as they are likely to become unusable
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (15.0 - post_residual as f64);
    }

    // Heuristic: If we have a lookahead item, favor bins where the post_residual 
    // can accommodate the next item. This is a Best-Fit-Lookahead variant.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else {
            score += 10.0; // Penalize bins that will definitely force a new bin for the next item
        }
    }

    // Harmonic class logic: Favor bins that leave a residual which is a multiple of 
    // common item sizes (20, 25, 33), as these are mathematically more likely to be filled.
    let harmonic_fit = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_fit * 0.5;

    // Progression logic: As the stream nears completion, become more aggressive 
    // about packing into existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is low or the item is large
        // This prevents creating a new bin for small items early in the stream.
        if fitting_bins_count > 0 {
            score += 40.0 + (item_size as f64 * 0.5);
        } else {
            score -= 5.0; // Neutralize penalty if it's the only option
        }
    }

    // Penalize bins that deviate too far from the mean residual (load balancing)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit typical items (< 10)
    // but large enough to be wasted (1..9).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the remaining space,
    // reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Reward if next_item_size leaves almost no space
        if gap < 5.0 {
            score -= 15.0;
        }
    }

    // 3. Open Bin Pressure: If this is the only bin that can fit the item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Thresholding: If evaluating a new bin, penalize based on current bin count
    // to discourage fragmentation across too many bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        // Only consider a new bin if the mean_residual is already very low, indicating we are "tight"
        if mean_residual > 20.0 {
            score += 40.0;
        }
    }

    // 5. Progression Weighting: As the stream nears completion, prioritize tighter packing
    // to close out existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin: only open if the fit is perfect or forced.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin can fit the item
            score += 150.0;
        } else {
            // If no other choice, base score is neutral
            score += 0.0;
        }
    }

    // 2. Lookahead matching: prioritize bins that leave space matching the next item perfectly.
    // If post_residual is close to next_item_size, we reward it to facilitate future packing.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // Penalize if the next item won't fit at all in this specific bin post-placement
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // 3. Efficiency heuristic: prioritize Best-Fit behavior (minimizing post_residual)
    // but balance against the mean residual to keep bin space usage uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. Progression weighting: as the stream nears the end, become more aggressive 
    // about filling bins to reduce the number of stragglers.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // 5. Penalize creating "fragmented" bins (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small for common items
    // If post_residual is small but > 0, it's often wasted.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else if post_residual > 0 {
            score += 10.0; // Penalize bins that leave too little space for the next item
        }
    }

    // Global state: If we are late in the stream, be more conservative with opening new bins
    if is_new_bin {
        score += 20.0 * (1.0 - progress);
        // If we have many bins open, penalize opening another one
        score += open_bins_count as f64 * 2.0;
    } else {
        // If this is the only bin that fits the current item, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Dynamic thresholding: Favor bins closer to the mean_residual to keep distribution balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Final adjustment: favor tighter fits as the stream progresses
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left in the bin. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": 
    // Small residuals are often unusable (1-9). We penalize them proportionally to their size.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // we strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_res - next_item_size as f64) / 100.0);
    }

    // Adaptivity: As the stream progresses, prioritize filling bins more tightly 
    // to avoid leaving fragmented space near the end of the stream.
    score += (progress * 10.0) * (post_res / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily early on,
    // but allow it to be chosen if the open bins are "too full" or offer poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score = 45.0 + (progress * 10.0);

        // If we have few bins open, we prefer reusing existing ones.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If the bin is already open, reward it for being a "better fit" 
        // relative to the mean residual of all open bins.
        if post_res < mean_residual {
            score -= 5.0;
        }
    }

    // Critical constraint: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #531: Harmonic-Residual Balancing
    // Strategy: Penalize small fragments that cannot accommodate future items (next_item_size).
    // Prioritize tight fits (Best-Fit principle) but modulate based on lookahead feasibility.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is small but > 0, it's often a waste.
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead coupling: If a bin can fit the next item, reward it.
    // This reduces fragmentation by encouraging bins that stay "useful" for the next step.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Harmonic adaptation: Favor bins that align with the mean_residual of the system.
    // This keeps the pack density uniform across all open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 4. Thresholding: Avoid opening a new bin unless the fit is extremely poor.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Only pick a new bin if the current fitting options are extremely poor (many small residuals).
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // 5. Progression scaling: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that fall into 
    // the "unusable" range (between 1 and 9). If post_residual is 0, it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If we are looking at a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other bins that can fit the current item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0;
        } else {
            score -= 10.0;
        }
    }

    // 3. Lookahead Integration: If the next item exists, penalize bins that cannot fit it
    // if the current bin is the only one left, or reward bins that leave enough space
    // to accommodate the next item (Best Fit logic).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;  // Penalty for creating a bin that is too small for next item
        }
    }

    // 4. Global Density Awareness: Penalize creating new bins if the existing mean_residual
    // is already high, indicating we should be filling existing bins more efficiently.
    if bin_residual == bin_capacity && mean_residual > 30.0 {
        score += 30.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping many bins open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": residuals smaller than the smallest likely items
    // but larger than 0. If post_residual is in (0, 10), it's highly inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
