    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 20.0;
        }
    }

    // 5. Progression: As the stream nears completion, become more aggressive 
    // about filling existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-residual space (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for leaving a very small, unusable gap (fragmentation).
    // A residual between 1 and 9 is often "dead space" since min item size is 1.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item.
        } else {
            score += 5.0;  // Penalty if current placement blocks next item.
        }
    }

    // Dynamic thresholding: as we approach the end of the stream, 
    // become more aggressive about filling existing bins to avoid new ones.
    let urgency = progress * 20.0;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with how much space is left in other bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Base cost of opening a new bin is high.
            score += 45.0 + (mean_residual * 0.5) - urgency;
        } else {
            score = 0.0; // Must open the first bin.
        }
    } else {
        // If it's an existing bin, favor bins that are already "tight" (low residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // If this is the only bin that fits the item, prioritize it highly.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
