        // If this bin is the only one that can fit the item, reward placing it here.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Non-linear coupling: penalize bins that deviate significantly from the mean residual.
        // This encourages "leveling" the fill across all open bins.
        let deviation = (post - mean_residual).abs();
        score += 0.2 * deviation.powf(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
