        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // 5. Progression scaling: As we reach the end of the stream, be more conservative 
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

