pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: Minimize dead space while prioritizing bins that can accommodate the next item.
    // The objective is to keep residuals either near 0 (perfect fit) or large enough to host upcoming items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a "sliver" (unusable space < 10) unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
