    // Lookahead logic: If the next item cannot fit in this post_residual, penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Harmonic preference: Favor bins that are already "half-full" or better to cluster residuals.
    let current_fill = bin_capacity - bin_residual;
    if current_fill > 0 {
        score -= (current_fill as f64 / bin_capacity as f64) * 10.0;
    }

    // If this is the only bin that can fit the item, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // If we are considering a new bin (bin_residual == bin_capacity):
    // Only open if the mean residual is high, suggesting current bins are inefficient.
    if bin_residual == bin_capacity {
