            score -= 5.0;
        } else {
            // Otherwise, strongly discourage opening a new bin unless necessary.
            score += 40.0;
        }
    }

    // Modulo-based penalty to discourage creating "awkward" residuals that don't divide common item sizes.
    score += (post_residual % 13) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
