        // Base cost of opening a new bin is high.
        score += 45.0;
        // Reduce the cost if we are forced to (no other bins fit).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 5. Progression weighting: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to reduce the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating 'orphaned' small spaces (under 10 units) which are rarely usable
    if post_residual > 0 && post_residual < 10 {
