    }

    // Global state awareness: if we are near the end of the stream, prioritize tight packing
    if progress > 0.8 {
        score -= (100 - post_residual) as f64 * 0.5;
    }

    // Strategy for New Bin: Only open if current fitting options are poor (high post_residual)
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
