            score = 80.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward bins that bring the residual closer to the global mean, reducing fragmentation
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;

        // Penalize bins that are becoming isolated/hard to fill
        if post_residual < 20 && fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (Best-Fit principle)
    // We penalize larger post_residuals to keep bins packed tightly.
    let mut score = post.powi(2);

    // Dynamic penalty for opening new bins:
    // If the bin is new (bin_residual == bin_capacity), increase the cost
    // as the stream progresses to force consolidation of existing bins.
    if bin_residual == bin_capacity {
        score += 500.0 * (1.0 + progress.powf(2.0));
    }

    // Lookahead coupling:
    // If the next item is large, we strongly penalize bins that cannot accommodate it
    // after the current placement. We favor bins where the post_residual is >= next_item_size.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
