        }
    }

    // Entropy management:
    // Discourage creating too many open bins early in the stream.
    // If fitting_bins_count is low, we are reaching a "last chance" scenario.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Global load balancing:
    // Penalize bins that deviate significantly from the mean residual of the set.
    let residual_deviation = (post - mean_residual).abs();
    score += 10.0 * residual_deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

