    // Favor bins that align with the current global mean residual.
    // This maintains "balanced" filling, keeping residuals consistent across bins.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.2;

    // 4. Scarcity/Fitting Pressure:
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
