    // Avoid creating bins that deviate significantly from the mean residual of open bins.
    // This promotes uniformity and increases the probability of future fits.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // 5. Fitting Constraint:
    // If this is the only bin that can fit the item, prioritize it heavily to avoid 
