    // that is just slightly too small to fit the next item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 2.5
    } else {
        0.0
    };

    // Interaction with mean_residual: avoid placing items in bins that are 
    // significantly emptier than the average, preventing fragmented "empty" bins.
    let fragmentation_penalty = if !is_new_bin && (bin_residual as f64 > mean_residual * 1.2) {
        (bin_residual as f64 - mean_residual) * 0.5
    } else {
        0.0
    };

    // If this is the last chance to fit the item (fitting_bins_count == 1), 
    // provide a significant discount to prevent unnecessary new bin creation.
    let desperation_discount = if !is_new_bin && fitting_bins_count == 1 {
        -50.0
    } else {
        0.0
    };

    new_bin_penalty + tightness_score + lookahead_penalty + fragmentation_penalty + desperation_discount
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero (fragmentation).
    // If post_residual is small (1-9), it often creates "dead space" that cannot fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for perfect or near-perfect fit for the next item
            score -= (bin_capacity - post_residual) as f64 * 0.5;
        } else {
            // Penalty for bins that block the next item from fitting in this bin
            score += 25.0;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. Density Balancing: If we have many open bins, penalize leaving large residuals.
    // Use harmonic mean of current residuals to normalize the preference for "tighter" bins.
    if open_bins_count > 0 {
        let density_factor = (bin_residual as f64 - mean_residual) * 0.2;
        score += density_factor;
    }

    // 5. New Bin Threshold: If considering a new bin, apply a structural penalty
    // to force it only when existing bins are truly inefficient.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;

        // Progress-based scaling: become more conservative as the stream nears completion
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
