pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual after placement. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for opening a new bin:
    // Only apply if the current bin is empty (bin_residual == bin_capacity).
    // We scale this penalty by the progression of the stream to encourage 
    // tighter packing as we reach the end of the input stream.
    if bin_residual == bin_capacity {
