    // Penalty for creating "islands" of small space:
    // If the post_residual is small but > 0, it is often wasted.
    // We penalize values in the [1, 9] range non-linearly.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powf(1.5);
    }

    // Normalize against mean residual to prevent drifting into inefficient bin states
    score += (post - mean_residual).powf(2.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
