        score += (open_bins_count as f64) * 0.5;
    }

    // 4. Critical Threshold: If this is the only bin that fits the item,
    // strongly favor it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Logic: Only open a new bin if the current post_residual
    // is significantly better than the mean_residual of existing bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Always open the first bin.
        } else {
            // High threshold for opening a new bin to prevent fragmentation.
            score = 45.0 + (mean_residual * 0.2);
        }
    }

    // 6. Progress factor: Be more conservative with new bins towards the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" candidate (bin_residual == bin_capacity) 
    // more heavily as the stream progresses, forcing tighter packing later.
    let is_new_bin = bin_residual == bin_capacity;
    let base_penalty = if is_new_bin { 45.0 + (progress * 55.0) } else { 0.0 };

    // Primary objective: Minimize the post_residual (Best Fit).
    // We use a quadratic penalty for large residuals to favor tight fits.
    let fit_penalty = post * post / bin_capacity as f64;

    // Lookahead coupling: If next_item_size is large, penalize small post_residuals
    // that might trap the next item (creating "fragmentation").
    let lookahead_penalty = if next_item_size > 0 {
        let fits_next = post >= next_item_size as f64;
        if !fits_next && post < next_item_size as f64 {
            // If we can't fit the next item, penalize proportionally to how much space we waste
            (next_item_size as f64 - post) * 0.8
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Diversity control: If we have many open bins, penalize opening new ones further
    // to encourage consolidation.
    let consolidation_pressure = (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    base_penalty + fit_penalty + lookahead_penalty + consolidation_pressure
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (the tighter the fit, the better)
    // We normalize by capacity to handle the residual space exponentially.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave room for common item multiples
    // If the post_residual is a multiple of common item sizes, we keep it as a potential fit.
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 10) as f64 * 2.5;
        score += harmonic_penalty;
    }

    // 3. Lookahead Integration: If the next item is large, avoid bins that would be too small for it
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // High penalty for "fragmenting" a bin that could have held the next item
        score += 50.0;
    }

    // 4. Thresholding: Avoid creating "dead" space (residuals < 10 are often unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 5. Open Bins Management: Penalize creating a new bin unless existing ones are forced to be poor fits
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Only return a low score if the number of open bins is small or fitting_bins_count is 0.
        score = 65.0 + (open_bins_count as f64 * 0.5);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 6. Global Progression: As we approach the end of the stream, tighten the fit requirement
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit typical items (< 10)
    // but large enough to be wasted (1..9).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead Synergy: Reward placements that leave exactly enough space for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Penalty for stranding the next item
            score += 20.0;
        }
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already open.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Discourage new bin if we have plenty of fitting options
        score += (fitting_bins_count as f64) * 10.0;
    } else {
        // Favor bins that are already "half-full" to consolidate space
        score += (bin_residual as f64) * 0.2;
    }

    // 4. Mean Residual Balancing: Avoid deviating too far from the average bin utilization.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to encourage tight packing.
    // We prioritize bins that result in the smallest post_residual (Best-Fit).
    score += (post_residual as f64) * 1.5;

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, 
    // significantly reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if it leaves very little space after the lookahead item.
        let post_post_residual = post_residual - next_item_size;
        score += (post_post_residual as f64) * 0.5;
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current 
    // fitting options are extremely poor (i.e., they result in high post_residuals).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual of current bins is high,
            // meaning we are cluttering bins with too much dead space.
            score += 45.0 + (mean_residual * 0.8);
        }
    }

    // 4. Scarcity/Efficiency: If this is the last fitting bin, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression Weighting: As the stream nears completion, become more 
    // conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize large gaps left behind (Best Fit logic)
    // Small post_residual is good, so we keep it as the baseline.

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Control: Penalize bins that would be left with tiny, 
    // unusable space (e.g., < 10), as these are "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 4. Global State Awareness: If we are late in the stream, be more aggressive 
    // about using existing bins to avoid opening new ones.
    if !is_new_bin {
        score -= (progress * 10.0);
    } else {
        // Penalize opening a new bin significantly, but allow it if existing bins 
        // are poor fits (high mean_residual).
        score += 30.0 + (mean_residual * 0.5);
    }

    // 5. Urgency: If this is the last fitting bin, prioritize it to prevent 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 6. Capacity Efficiency: Reward bins that become nearly full (post_residual near 0).
    score -= (1.0 / (post_residual as f64 + 0.1)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the remaining space (Best Fit principle).
    // We penalize larger post_residual to keep bins tightly packed.
    let mut score = post;

    // Interaction 1: Penalize opening new bins early in the stream.
    // If it's a new bin (bin_residual == bin_capacity), increase cost early,
    // but allow it late in the stream to avoid fragmentation.
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * (capacity * 0.75);
    }

    // Interaction 2: Coupling with lookahead.
    // If the next item is large and the current post_residual is small,
    // this bin becomes a "dead zone". We penalize post_residual ranges
    // that are smaller than next_item_size but non-zero.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post > 0.0 && post < next_item {
            // This creates a "gap trap" penalty.
            score += (next_item - post) * 1.5;
        }
    }

    // Interaction 3: Mean residual balancing.
    // If this bin's post_residual is significantly worse than the mean,
    // penalize it to encourage homogeneity across bins.
    if open_bins_count > 0 {
        let diff = (post - mean_residual).abs();
        score += diff * 0.5 * progress;
    }

    // Interaction 4: Last chance penalty.
    // If this is the only bin that fits the item (fitting_bins_count == 1),
    // reduce the score (reward) to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (capacity - post) * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

