    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: only do it if the average residual is already small
        // or if we are nearing the end of the stream.
        score += 45.0 + (mean_residual * 0.5);
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
        // or leave space for the next item.
        let rem = post_residual % 20;
        score -= (20 - rem) as f64 * 0.2;

        // 3. Lookahead Logic: If next_item_size fits in post_residual, reward this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
            // Further reward if the post_post_residual is very small (near 0)
            let tight_fit = (post_residual - next_item_size) as f64;
            score += tight_fit * 0.5;
        }

        // 4. Density Balancing: Penalize bins that deviate significantly from the mean residual
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Progression scaling: As we reach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit typical future items (e.g., < 10).
    // This is the "Best Fit" refinement: we prioritize placements that leave larger, more usable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 * (next_item_size as f64 / post_residual as f64);
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current best fit is objectively poor.
    // If the bin is new (bin_residual == bin_capacity), penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If other bins can fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness bias: Favor bins that are already partially filled (lower mean_residual) to keep clusters tight.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
