    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 5. Progression adjustment: Be more aggressive early on, conservative near the end
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean residual pressure:
    // If our post_residual is significantly better (lower) than the current average, reward it.
    if (post_residual as f64) < mean_residual {
