}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead space" (small residuals that are hard to fill).
    // An ideal fit leaves 0 remaining space.
    // We treat post_residual as a cost, but apply a non-linear penalty for "fragmentation" 
    // where the remaining space is too small to fit typical future items.
    let fragmentation_penalty = if post_residual > 0 && post_residual < 15 {
        (15.0 - post_res) * 2.5
    } else {
        0.0
    };

    // Factor in the lookahead: If next_item_size is large, we want to prioritize 
    // keeping bins open that have enough capacity to hold it.
    let lookahead_pressure = if next_item_size > 0 {
        if post_residual >= next_item_size {
            -15.0 * (next_item_size as f64 / 100.0) // Reward bins that can accommodate the next item
        } else {
            10.0 * (next_item_size as f64 / 100.0)  // Penalize bins that will strand the next item
        }
    } else {
        0.0
    };

    // Normalize open bins impact: as the stream progresses, we want to be more conservative 
    // about opening new bins, favoring packing into existing ones.
    let new_bin_bias = if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Penalize opening a new bin heavily as the stream progresses.
        25.0 + (progress * 50.0) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Coupling: Use mean_residual to adjust the desirability of the current fit.
    // If we are significantly below the mean, this bin is "tight", which is good.
    let efficiency_bonus = (post_res - mean_residual).max(0.0) * 0.2;

    let score = post_res + fragmentation_penalty + lookahead_pressure + new_bin_bias + efficiency_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
