    base_score + gap_penalty + lookahead_penalty + scarcity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // We favor bins that result in small remainders.

    // 2. Harmonic/Modulo Logic: Penalize remainders that are "awkward" 
    // Small remainders < 10 are often "dead space" that cannot fit subsequent items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 3. Lookahead Strategy (k=2): 
    // If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Bin Scarcity: 
    // If this is the only bin that can fit the current item, prioritize it heavily
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. New Bin Thresholding:
    // If evaluating a brand-new bin (bin_residual == bin_capacity):
    // Only open a new bin if the current mean_residual is very tight (e.g., < 15),
    // otherwise, force the item into existing bins to improve packing density.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            score += 100.0; // Discourage opening a new bin if existing bins have capacity
        } else {
            score += 35.0;  // Baseline cost for opening a new bin
        }
    }

    // 6. Progressive Density Adjustment:
    // As the stream progresses, prioritize filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize gaps that are too small to be useful (e.g., < 10).
    // If a bin has a residual after placement that is smaller than the smallest possible item (10),
    // it is highly likely to become 'dead space'.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Penalize opening new bins when current ones have space.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have many fitting bins, opening a new one is almost always bad.
        if fitting_bins_count > 0 {
