    // 4. Global balance: Prefer bins that stay close to the mean residual of the system
    // to keep the bin distribution uniform, reducing the likelihood of creating many 
    // bins with tiny, unusable residuals simultaneously.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Final adjustment: Strongly favor tight fits (Best Fit effect).
    // The lowest post_residual is usually the best, provided it's not in the dead zone.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
