        score -= (bin_capacity as f64 - post) * 0.1;
    }

    // If this is the last chance to fit the item in an existing bin, reduce the score
    // to make it more attractive than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize high numbers of open bins to encourage consolidation
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
