        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based 
    // on how many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 1.5);
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // reduce score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If our current bin is significantly worse than 
    // the mean residual of open bins, penalize it to force consolidation.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin if we have options.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 85.0; 
