    // 2. Best-Fit logic: Prefer smaller post_residual.
    // We already have post_residual in score. Now punish large gaps.
    score += (post_residual as f64) * 0.2;

    // 3. Lookahead Matching: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
