        score -= progress * 20.0;
    }

    // 5. Mean Residual Alignment: Avoid bins that deviate significantly from average density.
    // This encourages "leveling" the bins to keep them equally available for future items.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

