    // If the post_residual is small but not zero, it might be "dead space".
    // We penalize values that are not multiples of common item sizes (e.g., 20, 25).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual % 20) as f64 * 1.5;
    }

