            score = 40.0;
        }
    }

    // 5. Progression Scaling:
    // Toward the end of the stream, prioritize clearing smaller bins to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    // 6. Fragmentation Penalty:
    // Avoid leaving bins with residuals that are unlikely to fit future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
