    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 6. Mean Residual Sensitivity: If the average open bin is emptier than the current 
    // placement would leave this bin, we prefer this bin to improve overall utilization.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small, unusable gaps.
    // Gaps < 10 are almost useless given the 10-100 item distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Adaptive New-Bin Threshold: 
    // If this is a new bin (bin_residual == capacity), calculate the cost of opening it.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high to encourage filling existing ones.
        // We reduce this cost if we are early in the stream or if existing bins are poorly utilized.
        let progress = step_index as f64 / total_items as f64;
        score = 35.0 + (progress * 15.0) + (open_bins_count as f64 * 0.5);
    } else {
        // 3. Fitting Bin Pressure: 
        // If this is the only bin that fits the item, reward placing it here to avoid new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // 4. Lookahead Synergy:
        // If there is a next item, prefer bins where the post_residual is large enough to accommodate it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0;
            } else if post_residual > 0 {
                // Penalize placements that block the next item from fitting in this bin.
                score += 10.0;
            }
        }
    }

    // 5. Global Balance: Penalize increasing the number of active bins too aggressively.
    score += (open_bins_count as f64).powf(1.2) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for common items.
    // If post_residual is small but > 0, it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: reward bins where the post_residual can perfectly or 
    // nearly fit the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
