            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalize if the next item won't fit, but only if we have few bins open
            score += 15.0 / (fitting_bins_count as f64 + 1.0);
