    }

    // 4. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity),
    // heavily penalize it unless the current fit quality (post_residual) is extremely poor
    // across all available options.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (e.g., no other options)
        // or if all other fitting bins result in very poor future packing.
        score += 65.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Final adjustment: Prefer bins that leave the bin nearly full (post_residual -> 0)
    score += post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
