        let deviation = (post_residual as f64 - 12.0).abs();
        score += deviation * 0.5;
    }

    // 4. Scarcity avoidance: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize new bin creation exponentially as the stream progresses to consolidate space.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        25.0 + (progress * 50.0).powf(1.5) 
    } else { 
        0.0 
    };

    // Calculate the "tightness" of the fit. 
    // We want to minimize post_residual, but heavily penalize values that are too small 
    // to fit the next item (creating "dead space" that cannot be filled).
    let next_item_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * 1.5
    } else {
        0.0
    };

    // Favor bins that are already closer to the mean residual to keep bin levels balanced,
    // but only if we aren't creating a new bin.
    let balance_factor = if !is_new_bin {
        (post_res - mean_residual).abs() * 0.2
    } else {
        0.0
    };

    // The core heuristic: prioritize the smallest post_residual (Best Fit), 
    // tempered by the dynamic penalties calculated above.
    let score = post_res + new_bin_penalty + next_item_penalty + balance_factor;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Dead Space" avoidance)
    // Residuals between 1 and 9 are usually detrimental for future packing.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for preserving compatibility with the next item
            score -= 20.0;
        } else {
            // Penalty if this placement kills the ability to fit the next item
            score += 15.0;
        }
    }

    // 3. Pressure management: If we have many open bins, penalize opening new ones.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 50.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Tightness bias: Favor bins that are already tight (Best Fit logic)
        // We reward bins that result in a very small post_residual (Best Fit).
        score -= (100.0 - bin_residual as f64) * 0.1;
    }

    // 5. Global state adjustment: As the stream progresses, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if post_residual == 0 {
        // Perfect fit is always highly desirable
        score -= 30.0;
    }

    // 6. Distribution balance: Penalize bins that deviate significantly from the mean_residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
