    // Penalty for creating a "sliver" (fragmentation) that cannot fit common item sizes
    // We penalize residuals that fall into the range [1, 9] as they are highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item could fit into the current post_residual, 
    // prioritize this bin to maximize bin utilization (Best Fit variant).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Harmonic/Modulo logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25)
    // to keep the bin state "clean" for future items.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // Heuristic for opening a new bin:
    // If the bin is new, we apply a base cost. We only choose a new bin if the 
    // existing fitting bins result in a worse score than this base threshold.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is adjusted by the mean residual of current bins.
        // If current bins are very empty (high mean_residual), opening a new one is expensive.
        score = 45.0 + (mean_residual * 0.5);
    } else {
        // If it's not a new bin, penalize bins that deviate significantly from the mean_residual
        // to encourage balancing the load across all open bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Urgency factor: If this is the only bin that can fit the item, reward it to avoid
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance with lookahead and pressure-sensitive thresholds.
    // We prioritize bins that leave the smallest positive residual (Best Fit).
    // If post_residual is < 10, it's considered "dead space" (unusable for any item > 10).
    // We heavily penalize creating small dead gaps unless it's the last item or we have too many open bins.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (residual < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: If next_item_size is large, avoid leaving a residual that cannot fit it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Pressure factor: If we have many open bins, we become more desperate to fill existing ones
    // and less inclined to open new ones.
    let pressure = open_bins_count as f64 * 2.0;

    // If the bin is new (empty), apply a base penalty proportional to open bin count
    // to force the algorithm to prefer existing bins.
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    }

    // If this is the only bin that can fit the item, give it a significant bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Reward bins that stay close to the current mean residual to maintain packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize leaving small, unusable gaps.
    // If post_residual is very small (< 10), it's often a "dead" space trap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tighter alignment with the next item
        score -= (15.0 - diff).max(0.0);
    }

    // 3. Density Balancing: Compare post_residual against the global mean_residual.
    // If this bin's new residual is significantly higher than the mean, it's inefficient.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Strategic New Bin Avoidance: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily unless 
    // it's the only way to fit the current item or the current open bins are very full.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the mean_residual of existing bins is already very low (< 15)
            if mean_residual > 15.0 {
                score += 40.0;
            } else {
                score += 100.0; // Strong penalty for opening new bins prematurely
            }
        }
    }

    // 5. Progression Weighting: As the stream nears the end, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late game: prioritize filling bins to capacity (lower residual)
        score -= (100.0 - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too empty (high post_residual), 
    // but only if it's not a new bin (where we expect high residual).
    if !is_new_bin {
        score += (post_residual as f64).powf(1.5) * 0.1;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further refine: prioritize tighter fits for the next item
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // Global state awareness: If we have many open bins, penalize opening a new one.
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
        // Late game strategy: As we approach the end, be more aggressive with new bins 
        // if the current fit is poor (high post_residual).
        score -= progress * 20.0;
    }

    // Dead-space avoidance: Penalize bins that leave very small unusable gaps 
    // (assuming minimum item size is ~10).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 10.0;
    }

    // If this is the only bin that fits, prioritize it unless it's a terrible fit.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize opening new bins heavily, but scale this penalty by the progression of the stream.
    // Early in the stream, we are aggressive. Late in the stream, we are conservative.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        45.0 * (1.0 - (0.5 * progress))
    } else {
        0.0
    };

    // Calculate a "fit quality" score. 
    // We want to minimize the post-residual (Best Fit), but we penalize very small residuals (dead space)
    // that are too small to accommodate common future items.
    // We use the next_item_size to predict if the current post_residual will be "wasted".
    let dead_space_penalty = if post > 0.0 && post < (next_item_size as f64 * 0.8) {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Interaction between mean_residual and current fit: 
    // If the mean residual is high, we prefer to fill bins more densely (lower post).
    // If fitting_bins_count is 1, we are at a bottleneck; prioritize this bin to avoid opening new ones.
    let bottleneck_bonus = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    let score = post + 
                (post * 0.5 * progress) + 
                dead_space_penalty + 
                new_bin_penalty + 
                bottleneck_bonus + 
                (mean_residual * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: prioritize small post_residuals.
    // However, we penalize "dead space" that is too small for any likely future item.
    // If post_residual < 10 (minimum item size), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // we should prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic class alignment: favor residuals that are multiples of common item sizes
    // to keep bins "open" for standard chunks.
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 4. New bin management: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we are forced to.
        score += 35.0;

        // If there are other bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 45.0;
        }
    }

    // 5. Global state normalization: if we are near the end of the stream, 
    // be more aggressive about filling existing bins to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 6. Balance the load: avoid overcrowding if we have many open bins.
    // If we have many bins, prefer the one with the smallest current residual 
    // to consolidate items.
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit future items.
    // If post_residual is in (0, 10), it creates 'dead space' since min item size is likely 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Bin Pressure: If this is the only bin that fits the item, make it highly attractive to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Global Consolidation: Penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // Penalize opening a new bin early in the stream unless necessary.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 15.0;
    }

    // 5. Balance residuals: Prefer bins that stay closer to the current mean residual to keep packing density uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Aggressive 2-step lookahead matching
    // We prioritize bins that result in a post_residual that is either:
    // 1. Perfectly matched to the next_item_size (minimizing wasted space).
    // 2. Sufficiently large to accommodate the next item while keeping the bin efficiency high.

    let mut score = post_residual as f64;

    // 1. Penalize creating a new bin unless absolutely necessary (fitting_bins_count == 0)
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 500.0;
    }

    // 2. Lookahead matching: If next_item_size can fit in the post_residual, 
    // heavily reward bins where the remaining space after the next item is minimal (Best Fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let secondary_residual = post_residual - next_item_size;
        // Reward small secondary residuals (near-perfect packing)
        score -= (100.0 - secondary_residual as f64) * 2.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize bins that will be "trapped" and unable to take the next item
        score += 20.0;
    }

    // 3. Balance against mean_residual to prevent fragmentation
    // If this bin's post_residual is significantly worse than the average, penalize it
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Density focus: prefer bins that are nearly full (low post_residual)
    // This naturally favors Best Fit behavior.
    score += (bin_capacity - post_residual) as f64 * 0.1;

    // 5. Progression adjustment: In the final stages, be more conservative with opening new bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: The space left if we pick this bin. 
    // We want to minimize post_residual (Best Fit), but penalize fragmentation.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: If the post_residual is too small to fit typical future items,
    // it becomes "dead space". We penalize post_residuals in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we should prioritize this bin even if the post_residual is slightly larger.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global State: If we are near the end of the stream, prioritize filling existing bins
    // to avoid leaving half-empty bins at the end.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. New Bin Handling: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if the current fit is extremely poor (post_residual > 40).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins can take the item.
            score += 60.0;
        } else {
            // If no bins fit, the new bin is mandatory (base cost).
            score = 0.0;
        }
    }

    // 5. Balance: Favor bins that stay close to the mean residual to keep bin levels uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too small for common future items
    // If post_residual is very small (e.g., < 10), it creates "dead space"
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead: If next_item can fit in this post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 * (1.0 - progress);
    }

    // Heuristic for opening new bins: 
    // Only open a new bin if the mean residual is high enough that we aren't wasting space,
    // or if the stream is nearing the end and we want to consolidate.
    if is_new_bin {
        // Base cost for opening a new bin is high to favor existing bins
        score = 45.0 + (mean_residual * 0.5);

        // As the stream progresses, make it slightly easier to open a new bin 
        // to avoid "bad" fits that constrain the end-game
        score -= 10.0 * progress;
    } else {
        // If it's an existing bin, reward it if it's the only one that fits
        if fitting_bins_count == 1 {
            score -= 5.0;
        }

        // Penalize bins that deviate too far from the current mean residual
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.2 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
