    // which is too small for any item in the 10-80 range (since min item is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // This helps align bin space with future item patterns.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // 3. Lookahead Synergy: If the next item can fit in the current post_residual,
    // strongly reward that bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Open-Bin Congestion: If we have many open bins, prioritize filling existing ones.
    // If we have few, be more selective to avoid fragmenting space.
    if fitting_bins_count == 1 {
        // Last chance to fit in an existing bin before opening a new one; make it attractive.
        score -= 20.0;
    }

    // 5. New Bin Thresholding: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Penalize the new bin unless we have high fragmentation (mean_residual is very low).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 30.0 + (mean_residual * 0.5);
        }
    }

    // 6. Progress Scaling: As we approach the end of the stream, be more aggressive
    // about fitting items into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
