    // Given the range 10..100, residuals < 10 are effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, prioritize bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin slightly to keep it for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have existing bins that can fit the item.
