        // 4. Tight Fit Reward: Reward placing into bins that are already "fuller" (Best Fit logic).
        // We subtract a value proportional to the fullness to keep the bins tight.
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // 5. Stream Progression: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 5 {
        score -= 10.0;
    }

