pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Lookahead optimization: Reward placement if post_residual is close to next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // If the current placement makes the next item fit perfectly, heavily reward it
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. New bin penalty: Only open a new bin if the current fit is terrible (e.g., > 40)
    // or if we have very few open bins and the fit is suboptimal.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one is available
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Necessary evil: opening first bin
            score = 0.0;
        }
    }

    // 4. Mean residual balancing: Penalize creating bins that deviate significantly from the mean
    // This keeps bins packed at similar densities
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: reward smaller post_residual (tighter packing)
    // The base score is already post_residual.

    // 2. Lookahead Penalty: If next_item_size is large, avoid creating a post_residual 
    // that is slightly smaller than next_item_size, as it creates "orphaned" capacity.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize creating a bin that cannot fit the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. New Bin Threshold: If we are near the end of the stream, be more aggressive
    // about using existing bins to avoid opening new ones.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalty for opening a new bin scales with stream progress
        score += 25.0 * (1.0 + progress);
    }

    // 4. Global State Awareness: If the current mean residual is high, we are 
    // fragmenting bins. Penalize bins that increase fragmentation.
    if post_residual < (mean_residual as u32 / 2) && post_residual > 0 {
        score += 10.0;
    }

    // 5. Urgency: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Avoid "Dead Zone" residuals: Residuals between 1 and 9 are often 
    // unusable given the typical item distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": residuals too small for typical items (e.g., < 15)
    // are often worse than slightly larger residuals unless they hit exactly 0.
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res) * 2.0;
    }

    // Lookahead coupling: if the next item is large, prioritize keeping the residual 
    // large enough to accommodate it, or pack tightly if the current fit is near perfect.
    if next_item_size > 0 {
        let diff = (post_res as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5 * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive about
    // packing into existing bins to minimize the total count of open bins.
    let density_penalty = (open_bins_count as f64 / (1.0 + mean_residual)) * progress * 10.0;
    score += density_penalty;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold.
    // We only open a new bin if the "cost" of the best existing fit is worse than this constant.
    if bin_residual == bin_capacity {
        // As progress increases, the cost to open a new bin increases to force consolidation.
        score = 25.0 + (progress * 50.0);
    }

    // If this bin is the last chance for the current item, reduce penalty to prevent 
    // creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We prefer bins that are nearly full after placement.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the post-placement residual, 
    // prioritize this bin heavily to avoid creating fragmented space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Harmonic refinement: favor bins that leave an even smaller remainder after the next item
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Thresholding: Penalize "near-misses" (small unusable residuals)
    // If post_residual is < 10, it's often wasted space unless it fits the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. New Bin Logic: Discourage opening a new bin unless the current mean residual
    // is already very low, indicating that current bins are too tight to accommodate future variance.
    if bin_residual == bin_capacity {
        score += 45.0; // Base cost for opening a new bin
        if mean_residual < 20.0 {
            score += 30.0; // Heavily penalize new bins if existing bins have plenty of space
        }
    }

    // 5. Fitting Constraint: If this is the only bin that fits, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progression Scaling: As we approach the end of the stream, 
    // prioritize tighter packing (lower residuals) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small to fit typical items (< 10), 
    // it's "toxic" dead space. We penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // we reward this placement to encourage "tight packing".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, apply a penalty proportional to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item, 
    // prioritize it to avoid forced new-bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Mean residual equilibrium: Favor bins that keep the overall mean residual 
    // close to a target of ~20 (balance between packing tight and leaving room).
    let deviation = (post_residual as f64 - 20.0).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on current average density to discourage premature opening
    if bin_residual == bin_capacity {
        score += (mean_residual * 1.5) + (open_bins_count as f64 * 2.0);
    } else {
        // 2. Best-Fit logic: Penalize large post_residuals (wasted space)
        score += post_residual as f64 * 0.5;

        // 3. Lookahead matching: Reward if post_residual is a perfect fit for the next item
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 40.0;
            } else if post_residual > next_item_size {
                // Reward if the remaining space is slightly larger than the next item
                score -= 10.0;
            } else {
                // Penalize if the next item won't fit here
                score += 20.0;
            }
        }
    }

    // 4. Pressure handling: If this is the last fitting bin, prioritize using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Dynamic normalization based on stream progression
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base penalty for creating a new bin: proportional to progress to discourage early waste
    if is_new_bin {
        score += 45.0 + (progress * 20.0);
    } else {
        // 2. Best-Fit logic: penalize large post_residuals (wasted space)
        // We reward bins that result in a tight fit (post_residual near 0)
        score += post_residual as f64 * 0.5;

        // 3. Lookahead integration: if next item fits in this bin, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }

        // 4. Global state pressure: if many bins are open, prioritize closing gaps
        // Penalize bins that create "dead space" (residuals too small for common items)
        if post_residual > 0 && post_residual < 15 {
            score += 25.0 * (1.0 - progress);
        }
    }

    // 5. Threshold adjustment: if this is the last chance for this item, 
    // heavily discount the penalty of a new bin to avoid blocking
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // 6. Dynamic balance: as we approach the end of the stream, 
    // become more aggressive about filling existing bins
    if progress > 0.8 {
        score += (post_residual as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post_residuals (Best Fit logic)
    // Non-linear coupling: square the post_residual to heavily penalize large gaps
    let mut score = (post_residual as f64).powi(2);

    // Penalty for opening a new bin
    if is_new_bin {
        // Only open a new bin if the progress is late, or if we have very few bins,
        // or if fitting the item into existing bins would leave a very poor residual.
        // We add a dynamic threshold based on progress.
        score += 500.0 * (1.0 - progress).powi(2) + 200.0;
    } else {
        // If it's an existing bin, reward matching the next_item_size if possible.
        // If post_residual is close to next_item_size, we create a perfect pair.
        if next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 150.0 / (1.0 + diff);
        }

        // Penalty for leaving a bin with a residual that is too small for any future item
        // (assuming min item size is ~10, anything < 10 is 'dead space')
        if post_residual > 0 && post_residual < 10 {
            score += 300.0 * (1.0 - progress);
        }
    }

    // Encourage filling bins that are already closer to capacity (mean_residual interaction)
    // If this bin's residual is much higher than the mean, it's a "wasteful" bin.
    let residual_penalty = (bin_residual as f64 - mean_residual).max(0.0);
    score += residual_penalty * 0.5;

    // If this is the only bin that can fit the item, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 400.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals to prioritize tight packing.
    // We penalize the post_residual linearly.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small (e.g., < 10), it is often a "perfect" fit for common item sizes.
    // We reward residuals that align with common small divisors of bin capacity (100).
    if post_residual > 0 && post_residual < 10 {
        score -= (10 - post_residual) as f64 * 5.0;
    }

    // 3. Lookahead Logic:
    // If a future item exists, evaluate if the current post_residual can accommodate it.
    // If next_item_size fits in the post_residual, drastically reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 2.0;
    }

    // 4. Threshold Logic for New Bin:
    // If bin_residual == bin_capacity (New Bin), penalize opening it based on open_bins_count.
    // We want to force usage of existing bins unless the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 12.0) + (mean_residual * 0.5);
    }

    // 5. Fitting Constraint:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // prioritize it to avoid fragmenting the bin space unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression Scaling:
    // As the stream nears completion (step_index -> total_items), be more aggressive 
    // about packing into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that fall into the "unusable" range (1..10).
    // These gaps are too small for any upcoming item (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }

    // 3. Global Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, apply a threshold penalty based on the number of open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If other bins can fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 200.0;
        }
    }

    // 4. Tightness bias: Prefer bins that are already "tighter" compared to the mean.
    // This packs bins more densely, keeping the number of open bins low.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins
    // by favoring placements that leave very small residuals (potentially zero).
    let progress = step_index as f64 / total_items as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless absolutely necessary.
    if bin_residual == bin_capacity {
        score += 100.0;
        // If there are other bins that can fit the item, strongly penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 200.0;
        }
    }

    // 2. Lookahead: prioritize bins that can accommodate the next item after this one.
    // If the post_residual is close to the next_item_size, we reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fits for the lookahead item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.5;
        } else {
            // If the post_residual is too small for the next item, penalize it slightly 
            // to encourage keeping larger spaces for future items.
            score += 5.0;
        }
    }

    // 3. Balance: penalize creating "dead space" that is smaller than the smallest likely items (10).
    // If the post_residual is between 1 and 9, it's very hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global state adjustment: prefer bins that are closer to the current average fullness.
    // This helps maintain a uniform distribution of residuals.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 5. Progression: As we reach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (small residual that won't fit common items).
    // If post_residual is < 10, it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Heuristic for opening a new bin:
    // Only open a new bin if the current fit is very poor (large post_residual)
    // or if we are early in the stream and need to keep bins balanced.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open
        } else {
            // Heavily penalize opening a new bin if existing bins can fit the item
            score = 200.0 + (mean_residual * 0.5);
        }
    } else {
        // Encourage using bins that bring the mean residual closer to a target
        // of ~20% capacity to leave room for future medium items.
        let deviation = (post_residual as f64 - 20.0).abs();
        score += deviation * 0.2;
    }

    // Final scaling: favor bins that are already partially full to keep open_bins_count low.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin (bin_residual == bin_capacity) increasingly as the stream progresses
    // to discourage fragmentation early and ensure density late.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 45.0 + (progress * 55.0) } else { 0.0 };

    // Best-fit approach: reward smaller post-residuals.
    // We add a non-linear penalty for "dead space" (post_residual).
    // The exponent 1.2 creates a convex cost function that discourages leaving too much space.
    let fit_score = post.powf(1.2);

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to keep the bin tight.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalize bins that are "almost full" but leave a sliver (e.g., 1-5 units) 
    // that is statistically unlikely to be filled, unless it's the end of the stream.
    let sliver_penalty = if post_residual > 0 && post_residual < 8 {
        (8.0 - post as f64) * 2.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Combine heuristics: 
    // Lower score is better.
    fit_score + new_bin_penalty + lookahead_bonus + sliver_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits that leave little room.
    // We heavily penalize post_residual values that are between 1 and 9 (the "sliver" trap).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively "waste" the next opportunity.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward bins that leave exactly enough space for the next item (synergy).
            let diff = post_residual - next_item_size;
            if diff < 5 {
                score -= 20.0;
            }
        }
    }

    // 3. Resource Pressure: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity (New Bin), apply a penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If there are other bins that could fit the item, strongly discourage starting a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Harmonic Alignment: Favor bins where the residual is a multiple of common item sizes (e.g., 20, 25).
    // This helps keep bins "aligned" for future items.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. Mean residual equilibrium: Avoid bins that deviate significantly from the average state.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
