    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. Lookahead interaction:
    // If the next item is large (e.g., > 50) and we can fit it in the current bin's remaining space,
    // we should prioritize bins that leave exactly enough room for that next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that have just enough room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // If the next item cannot fit, penalize this bin slightly to keep the space for a future fit.
            score += 2.0;
        }
    }

    // 6. Urgency: If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize creating small unusable slivers (dead space)
    // Small slivers (< 10) are extremely costly as they likely won't fit future items.
    let sliver_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powf(2.0) * 5.0
    } else {
        0.0
    };

    // Reward bins that align with the next item's size (lookahead)
    // If next_item_size fits, we want the current post_residual to be close to it.
    let lookahead_score = if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        if post >= next_item_size as f64 {
            -1.0 * (100.0 - diff) * 0.5
        } else {
            diff * 2.0
        }
    } else {
        0.0
    };

    // Dynamic thresholding: late in the stream, be more aggressive about filling bins
    // to avoid leaving too many half-empty bins open.
    let progress_bias = progress * 20.0;

    // Base score: prioritize tighter fits (Best Fit principle)
    // Add non-linear coupling with current mean_residual to balance packing density
    let base_score = post + (post * (mean_residual / bin_capacity as f64));

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // Only open if the current open bins are very poorly suited (high post_residual).
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) + (1.0 - progress) * 15.0
    } else {
        0.0
    };

    // Combine factors:
    // Lower score is better.
    base_score + sliver_penalty + lookahead_score + new_bin_penalty - progress_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero (fragmentation)
    // We favor "perfect fits" (post_residual == 0) and "large residual" bins.
    if post_residual > 0 {
        score += 20.0 / (post_residual as f64 + 1.0);
    }

    // 2. Next-Item Lookahead: If we can fit the next item in the same bin, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Modulo/Harmonic Class alignment: Reward packing that keeps residual 
    // aligned with common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_alignment = (post_residual % 25) as f64;
    score += harmonic_alignment * 0.2;

    // 4. Scarcity/Efficiency: If this is the only fitting bin, reward it heavily to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the existing options are very poor.
    if bin_residual == bin_capacity {
        // Higher penalty for new bins as the stream progresses to consolidate packing.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 20.0);
    }

    // 6. Mean Residual Balancing: If the bin's residual is significantly below the mean,
    // it's a "tight" bin. We penalize further filling to prevent creating "dead zones".
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
