    // If we have other options, make the new bin very expensive.
    if is_new_bin {
        if open_bins_count > 0 {
            score += 45.0; 
        }
        return score;
    }

    // Lookahead logic: if the next item fits perfectly into this post-residual,
    // we reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // Strong reward for small gaps after placing both current and next item
        score -= (30.0 - gap as f64 * 0.5);
    }

    // Heuristic: If this is the last chance for the current item, 
    // and the post_residual is "awkwardly small" (e.g., < 10), 
    // it creates dead space. Penalize small, unusable remainders.
    if fitting_bins_count == 1 && post_residual < 10 {
        score += 15.0;
    }

    // If the post_residual is significantly better than the current mean_residual,
    // it suggests this bin is becoming "too full" or "too empty". 
    // We prefer bins that stay close to the historical average to maintain balance.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Progress-based scaling: As we approach the end of the stream, 
    // become more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
