        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large empty spaces (waste) heavily, but modulate by stream progress.
    // Near the end of the stream, we become more aggressive in packing to avoid new bins.
    let waste_penalty = post * post * (1.0 + progress);

    // Lookahead logic: if the next item fits into the current post_residual, 
    // prioritize this bin to preserve future capacity.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -500.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), apply a penalty 
    // proportional to the current open bins to discourage fragmentation.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 50.0) + (100.0 * (1.0 - progress))
    } else {
        0.0
    };

    // Reward bins that have residuals close to the global mean to maintain uniformity,
    // which helps keep future fitting probabilities balanced.
    let uniformity_bonus = (post - mean_residual).abs() * 2.0;

    // Favor bins that are the last chance for the current item to avoid opening new bins unnecessarily.
    let urgency_bonus = if fitting_bins_count == 1 { -1000.0 } else { 0.0 };

    waste_penalty + lookahead_bonus + new_bin_penalty + uniformity_bonus + urgency_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (1..10)
    // that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item fits in the current post_residual, reward this bin.
    // This implements a "Best-Fit-Next" logic to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one unless 
    // the current fit is extremely poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening new bins if we have many bins already open
        score += (open_bins_count as f64) * 5.0;
        // Reward opening a new bin only if fitting_bins_count is low (forced to create waste)
        if fitting_bins_count > 0 {
            score += 100.0; 
        }
    }

    // 4. Harmonic Modulo Coupling: Prefer residuals that are multiples of common item sizes
    // (e.g., 20, 25, 33) to allow for future packing efficiency.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 15.0;
    }

    // 5. Progression Scaling: As the stream nears completion, prioritize closing bins
    // by aggressively filling them (reducing residual variance).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

