    // We heavily penalize post_residuals that fall into the [1, 9] range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Encourage "tight packing" by favoring bins that keep the post_residual low,
    // but only if it doesn't create a dead space.
    score += (post_residual as f64) * 0.1;

    // Penalize opening new bins when existing ones can fit the item.
    // If this is a new bin (bin_residual == bin_capacity) and other bins could fit it, add a heavy penalty.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
