        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Scale by open bin pressure: discourage adding more bins if we already have many open.
    score += (open_bins_count as f64) * 2.0;

    // Reward bins that bring the bin_residual close to the mean_residual of existing bins, 
    // to maintain a uniform distribution of fill-levels.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

