    }

    // 5. New Bin Logic: If this is a new bin (residual == capacity), penalize it heavily 
    //    unless all other options result in very poor fits (fragmentation).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily discourage opening a new bin if an existing one can fit the item.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other choice, normalize the cost to be competitive.
            score = 50.0;
        }
    }

    // 6. Progression Scaling: As we approach the end of the stream, prioritize closing bins
    //    by being more aggressive on existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
