    }

    // 3. Dynamic New-Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the current fitting bins are "too full" or "too empty" to accommodate future growth.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 65.0;

        // If we have very few bins open, be more conservative about opening new ones.
        if open_bins_count < 3 {
            score += 30.0 * (1.0 - progress);
        }
    } else {
        // We are considering an existing bin. 
        // Reward bins that are closer to the mean residual to keep distribution uniform.
        let diff_from_mean = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
        score -= diff_from_mean * 0.2;

        // If this is the last fitting bin, reward it to avoid opening a new one prematurely.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 4. Tightness bias: Prefer filling bins to capacity as the stream nears the end.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
