    // Reward bins that bring the mean residual closer to a "healthy" value (e.g., 20% of capacity).
    // This helps maintain a balance between filling bins and keeping capacity for future items.
    let target_mean = bin_capacity as f64 * 0.2;
    let mean_diff = (mean_residual - target_mean).abs();
    score += mean_diff * 0.5;

    // Penalize the "last chance" bin to prevent forcing items into bins that 
    // leave awkward residual sizes (e.g., 1-9), which are hard to fill later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 0 && post_residual < 10 {
