    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New Bin Logic: Only open a new bin if the current residual is significantly 
    // worse than the mean, or if no other bin is a good fit.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0; // Discourage opening new bins early
        } else {
