        score = 35.0 + (1.0 - progress) * 40.0;
    } else {
        // Global state heuristic: if current mean_residual is high, we have fragmented bins.
        // Penalize placing in bins that deviate significantly from the mean to encourage consolidation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;

        // If this is the only bin that can fit the item, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
