    // We add a penalty for empty space that is too small to fit common items (10-30 range).
    // The penalty is non-linear to prioritize tighter fits as the stream progresses.
    let mut score = post_res;

    // Penalty for creating a bin that is "almost" full but leaves small unusable gaps
    // if the next_item_size is large.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size as f64 - post_res).powf(1.5);
