        // Reward bins that keep the mean residual balanced
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.5;

        // Heavily penalize bins that become "fragmented" (very small residual) 
        // unless it's a perfect fit (post_residual == 0).
