        score -= 40.0;
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly from the 
    // current mean residual to maintain uniform bin usage (Best-Fit-Decreasing style).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
