pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // A base score of post_residual (Best Fit) is the foundation, 
    // but we adjust based on packing efficiency and lookahead.
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we are nearing the end of the stream.
        score += 45.0 + (mean_residual * 0.5) - (progress * 20.0);
    } else {
        // 2. Reward bins that leave a residual capable of fitting the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
