pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space. We want to minimize this (Best Fit strategy).
    let mut score = post;

    // Penalty for "fragmentation": If we leave a small sliver of space that is unlikely to be filled,
    // we penalize it. A "bad" sliver is between 1 and 9 (since min item size is 10).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item could fit in this bin, prioritize this bin.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 0.5;
    }

    // Dynamic thresholding: As the stream progresses, we become more conservative about opening new bins.
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as progress increases.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 25.0);
    }

    // Balancing: If we have many open bins, penalize using a new one or leaving a bin with high residual.
    // We want to keep open_bins_count low by favoring bins that are already "fuller" (lower post_residual).
    score += (open_bins_count as f64 * 0.2);

    // If this is the only bin that can fit the item, prioritize it to avoid wasting potential space
    // or being forced to open a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Non-linear coupling: Reward bins that align with the global mean residual to keep bin states uniform.
    let dev = (post - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Harmonic Class Logic: penalize residuals that cannot easily fit common item sizes (e.g., 20, 25, 33, 50)
    // We prioritize keeping residuals as multiples of common factors to maximize future packing efficiency.
    let harmonic_penalty = if post_residual > 0 {
        let factors = [20.0, 25.0, 33.0, 50.0];
        let mut min_dist = 100.0;
        for &f in &factors {
            let dist = (post_residual as f64 % f).abs();
            if dist < min_dist { min_dist = dist; }
        }
        min_dist * 0.5
    } else {
        -5.0 // Reward perfect fits
    };
    score += harmonic_penalty;

    // 3. Lookahead integration: If the next item fits into the current post_residual, drastically reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
