        if post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    // 4. Scarcity/Density management: 
    // If we have few fitting bins, penalize opening a new bin (where bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
