            score += 150.0; // Heavy penalty for opening a new bin if others exist
        } else {
            score -= 10.0; // Neutral baseline for mandatory new bin
        }
    }

    // 5. Progression adjustment: In early stages, favor tighter packing; in late stages, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
