        }
    } else {
        // Favor bins that have a residual close to the mean to maintain uniform packing.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Late-stage optimization: as we approach the end of the stream, 
    // prioritize clearing out the most fragmented bins.
    if progress > 0.8 {
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-placement residual (Best Fit principle).
    // Penalize small residuals (fragmentation) by squaring the post-residual.
    let mut score = post * post;

    // Favor bins that are "tight" relative to the lookahead. 
    // If next_item_size fits in this post-residual, heavily reward (subtract) this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 50.0;
