    // Dynamic pressure: As the stream progresses, discourage opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with progress, making it harder to open new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 2500.0 * (1.0 + progress.powf(2.0));
    }

    // Interaction with mean_residual:
    // If this bin's post_residual is significantly worse than the average, penalize it.
    // This prevents creating outliers in bin fullness.
    if post > mean_residual {
        score += (post - mean_residual).powf(1.5);
    }

    // If this is the only bin that fits the item (fitting_bins_count == 1),
    // reward it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 1000.0;
    }

    // Normalize against the number of open bins to keep the heuristic stable 
    // in long streams where open_bins_count might fluctuate.
    score + (open_bins_count as f64 * 2.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
