    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, we penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
