        // Bias towards bins that keep the bin usage close to the global mean
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual.
    // However, avoid "slivers" (very small residuals) that are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalty for creating unfillable gaps
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
