    // 3. Global State: If we are late in the stream, favor utilizing existing bins 
    // over opening new ones to minimize the total count.
    if fitting_bins_count > 0 {
        if bin_residual == bin_capacity {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 60.0 * (1.0 - progress);
        }
    } else {
        // If no bin fits, we MUST open a new bin.
        if bin_residual == bin_capacity {
            score -= 100.0; 
        }
    }

    // 4. Mean Residual Balancing: If the current bin is "emptier" than the average open bin,
    // it is a better candidate to absorb the item to keep the mean residual tight.
    if (bin_residual as f64) > mean_residual {
        score -= 15.0 * (1.0 - progress);
    }

    // 5. Thresholding for large items: If the item is large, prioritize bins where 
    // the post_residual is close to zero to maximize bin utilization.
    if item_size > 60 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit principle)
    // We use a quadratic penalty to strongly discourage large gaps (fragmentation)
    let mut score = post * post * 0.01;

    // Penalty for opening a new bin when existing bins are available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // As the stream progresses, increase the cost of opening a new bin 
        // to force consolidation, unless the residual is very tight
        score += 50.0 * (1.0 + progress);
