            // This is a "dead zone" for the next item
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Encourage filling bins that are already "half-full" to keep mean_residual balanced
    // This helps avoid creating many bins with very small residuals (which are hard to fill)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
