    // 2. Lookahead optimization: If the next item is large, prioritize bins 
    // that can accommodate it. If current bin cannot fit next_item, add penalty.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, 
    // become more aggressive in packing to avoid opening new bins.
    if fitting_bins_count > 0 {
        // If this is a new bin candidate, heavily penalize it unless 
        // the remaining open bins are all very poorly suited.
        if bin_residual == bin_capacity {
            score += 40.0 * (1.0 - progress * 0.5);
        }
    }

    // 4. Global State Balancing: Avoid fragmenting space across too many bins.
    // If the post_residual is below a "critical" threshold (e.g., < 10), 
    // it's likely "dead space" that cannot fit most items.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // 5. Mean residual pressure: If current bin is significantly better 
    // than the global average, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
