            score -= 45.0 + (next_item_size as f64 * 0.5);

            // Further reward if this placement brings the bin toward the global mean residual
            if (post_residual as f64) < mean_residual {
                score -= 10.0;
            }
        } else {
            // Penalty for stranding an item that could have been accommodated
            score += 20.0;
        }
    }

    // 3. New Bin Handling: Discourage opening a new bin unless the existing fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High baseline threshold to open a new bin. 
        // We only open if the average fit quality is already very low.
        score = 85.0 + (open_bins_count as f64 * 0.2);
    } else {
        // 4. Scarcity penalty: If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Progression adjustment: As the stream nears the end, be more conservative with space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
