    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Tightness bias: Favor bins that leave the residual close to the mean_residual
    // to keep bin utilization balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 5. Last Chance Logic: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead-based fragmentation avoidance.
    // We prioritize bins that leave the smallest residual, but penalize residuals that are 
    // too small to accommodate the next item (wasted space) or significantly deviate 
    // from the global mean residual.

    let mut score = post_residual as f64;

    // 1. Penalize new bin creation unless it's the only option or the current state is highly fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
