    // Favor bins that keep the residual close to the mean residual of the system
    // to keep the bin landscape uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin thresholding
    // If the bin is brand new (residual == capacity), we only choose it if 
    // the current scores of existing bins are extremely high (meaning they are bad fits).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage compaction
        score = 65.0 + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space < 10, as items are >= 10).
    // If post_residual is in [1, 9], it is effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Prioritize tight fits (Best-Fit principle).
    // We reward post_residual being close to 0, but heavily penalize the "new bin" case
    // if there are bins that can already fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 3. Lookahead: If the next item can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Global pressure: Penalize increasing the number of open bins as the stream progresses.
    // As we approach the end of the stream, we become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 5.0);

    // 5. Balance residuals: If this bin's residual is much smaller than the mean, 
    // it's a good candidate for "closing out" the bin.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

