    }

    // 2. Best-Fit logic: prioritize minimizing post_residual (Best Fit)
    // We already have post_residual in score, but we weight it heavily.
    score *= 1.2;

    // 3. Lookahead Matching: Reward placing an item such that the next item fits perfectly
    // If next_item_size is known, favor bins where post_residual is close to next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward cases where post_residual is slightly larger than next_item_size to leave room
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize cases where the next item won't fit at all in this specific bin
            score += 40.0;
        }
    }

    // 4. Global balance: Prefer bins closer to the mean residual to prevent "fragmentation"
    // This keeps the remaining space in open bins somewhat uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.3;

    // 5. Urgency: If this is the only fitting bin, prioritize it heavily to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // 6. Scale by progression: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
