pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As the stream progresses, we become more conservative (higher penalty for small fragments).
    let fragmentation_penalty = if post < 20.0 {
        (20.0 - post).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that can accommodate the lookahead item.
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin, penalize based on how many bins are already open 
    // to discourage excessive bin creation early in the stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) / (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that bring the residual closer to the mean_residual of existing bins,
    // encouraging uniform packing.
    let balance_reward = (post - mean_residual).abs() * 0.1;

    // Final score: lower is better.
    // Base score is post_residual (Best Fit logic); we modify with our heuristics.
    post + fragmentation_penalty + lookahead_reward + new_bin_penalty + balance_reward
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
