    // we only favor it if it's nearing the end of the stream or if all other 
    // options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0 * completion_factor;
    } else {
        // Favor bins that have a residual close to the mean, maintaining uniformity
        score += (post_res - mean_residual).abs() * 0.2;
    }

    // If this is the only bin that can fit the item, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

