    let progress = step_index as f64 / total_items as f64;

    // Base score: prefer tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize new bins heavily early on, but allow flexibility as we near end of stream
    if is_new_bin {
        score += 15.0 * (1.0 - progress);
        // Only open new if we have no other options or the fit is truly terrible elsewhere
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Reward bins that are becoming "full" to prioritize clearing them
        // Penalize bins that would leave a tiny, unusable sliver (1-9)
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Lookahead: if next item is large, favor bins that can accommodate it
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0;
            } else if post_residual < next_item_size && post_residual >= 10 {
                // If the current placement makes the bin unable to fit the next item,
                // but the current item is small, penalize this bin slightly
                score += 5.0;
            }
        }
    }

    // Use mean_residual to balance load across bins
    // If this bin is much emptier than the average, penalize it to keep bins tightly packed
    if !is_new_bin && (bin_residual as f64) > (mean_residual + 10.0) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

