    let mut score = post_residual as f64;

    // Penalty for creating a new bin:
    // We scale the cost of a new bin based on the progress of the stream.
    // Early in the stream, we are more conservative (higher penalty).
    // Late in the stream, we are more aggressive to consolidate remaining items.
    if is_new_bin {
        score += 15.0 + (35.0 * (1.0 - progress));
    }

    // Heuristic coupling:
    // If we have very few bins that can fit the current item, prioritize using them
    // to avoid the "new bin" penalty.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Lookahead interaction:
    // If the next item is large, prioritize keeping the post_residual high enough
    // to accommodate it, or conversely, if the current item fits perfectly (0 residual),
    // reward it heavily to clear the item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - progress);
        } else if post_residual < 10 && post_residual > 0 {
            // Penalize creating "slivers" (unusable space)
            score += 20.0;
        }
    }

    // Interaction with mean_residual:
    // If the current bin is significantly "fuller" than the average open bin,
    // it is a high-priority target for filling.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
