    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression: As we approach the end of the stream, be more aggressive with packing
    // to avoid leaving too many bins partially full.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin: Only open a new bin if the fit is truly desperate.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead matching: Reward bins where the post_residual is close to the next_item_size.
    // This minimizes future fragmentation by creating "perfect" fits.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 3. Fragmentation control: Penalize bins that deviate significantly from the mean_residual.
    // We want to keep bins packed similarly to facilitate future item fitting.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.3;

    // 4. Scarcity avoidance: If this is the last bin that can fit the current item, 
    // prioritize it to avoid forcing a new bin, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression adjustment: As the stream nears the end, prioritize tighter fits 
    // to clear out open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are often unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization (k=2)
    // If we have a next item, favor bins that can accommodate it after the current item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for keeping room for the next item
        } else {
            score += 15.0; // Penalty for stranding the next item
        }
    }

    // 3. Dynamic Thresholding for New Bin Creation
    // If this is a new bin, we only pick it if the Best-Fit/First-Fit options are extremely poor.
    if is_new_bin {
        // Base penalty for opening a new bin
        score = 80.0;

        // If we are near the end of the stream, discourage opening new bins unless necessary
        score += (progress * 40.0);

        // If there are many open bins with poor residuals, it's safer to use an existing one
        score += (open_bins_count as f64 * 2.0);
    } else {
        // 4. Global State Heuristic
        // Encourage using bins that bring the current bin's residual closer to the global mean.
        // This promotes uniform filling.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // If this is the last fitting bin, prioritize it to avoid opening a new one unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 5. Reward tightest fit (Best-Fit principle)
    // As the stream progresses, prioritize tightest packing to maximize capacity utilization
    score += (post_residual as f64) * (0.1 + progress * 0.4);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left after placement.
    // Lower residual is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if the post_residual is small but 
    // too large to fit the average remaining item (approximated by mean_residual), 
    // it becomes unusable. We penalize post_res values in the "danger zone".
    if post_res > 0.0 && post_res < 10.0 {
        score += 50.0 / (post_res + 0.1);
    }

    // Dynamic Lookahead: If next_item_size exists, favor bins that can 
    // accommodate both current and next items (Best Fit for the pair).
    if next_item_size > 0 {
        if post_res >= next_item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 15.0 * progress;
        }
    }

    // New Bin Thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), we only open it 
    // if the current fitting bins are extremely inefficient (high mean_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist, 
            // unless the mean residual of existing bins is already very high.
            score += 80.0 + (mean_residual * 2.0);
        }
    } else {
        // If it's an existing bin, reward it if it's the last chance (fitting_bins_count == 1).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Scale by progression: As we approach the end of the stream, 
    // prioritize tighter packing to reduce the final bin count.
    score += (progress * 10.0) * (post_res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual
    // We penalize larger post_residuals to favor tight packing
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // This reduces the creation of 'unusable' slivers
    let harmonic_penalty = if post_residual > 0 {
        (post_residual % 10) as f64 * 2.0 + (post_residual % 25) as f64 * 0.5
    } else {
        -50.0 // Huge reward for perfect packing (100% utilization)
    };
    score += harmonic_penalty;

    // 3. Lookahead Logic (Next Item):
    // If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin
    // to discourage "stranding" the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave "perfect" space for the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.1;
        }
    }

    // 4. New Bin Threshold:
    // If bin_residual == bin_capacity, this is a candidate for a new bin.
    // Only open a new bin if the current mean_residual is very low (implying we are already tightly packed)
    // or if fitting_bins_count is very low (we have no good options).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Must open first bin
        } else {
            // Apply a heavy cost to opening a new bin unless existing bins are already "full"
            score += 45.0 + (mean_residual * 0.5);
            // If we have very few options (fitting_bins_count is low), make opening a new bin more attractive
            if fitting_bins_count <= 1 {
                score -= 20.0;
            }
        }
    }

    // 5. Progression scaling:
    // As we near the end of the stream, tighten the criteria to minimize new bin creation
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

