    if next_item_size > 0 {
        let gap_penalty = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64 * 1.2
        } else {
            -(post_residual - next_item_size) as f64 * 0.3
        };
        score += gap_penalty;
    }

    // Fitting density coupling:
    // If this is the only bin that fits, we are forced to use it.
    // If we have many options, we favor those that pull the mean_residual closer to 0.
    if !is_new_bin {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        if fitting_bins_count == 1 {
            score -= 20.0; // Strong incentive to use the last fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Dead Space" avoidance)
    // If post_residual is small but > 0, it's often a bad fit unless it's zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Class Logic: Prefer filling bins to specific thresholds
    // If we can fit the next item, reward this bin proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Pressure to consolidate: If there are many open bins, penalize opening a new one
    // or picking a bin that leaves a large, fragmented residual.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to how many bins are already open
        score += (open_bins_count as f64) * 5.0;

        // If we are at the end of the stream, penalize opening a new bin heavily
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    // 4. Fitting Density: If this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly from the average
    // This promotes "leveling" the residuals across the set of open bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Modulo-based preference: Favor bins that leave room for standard item size chunks (e.g., 25, 33, 50)
    // This helps in aligning future items into harmonic slots.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

