        // If other bins could have taken this item, strongly discourage opening a new one
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Balancing: Favor bins that are closer to the mean residual to maintain uniform bin usage
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead: reward bins where the post_residual can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
