    // If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Progression adjustment:
    // As we approach the end of the stream, prioritize closing bins (minimizing residuals)
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The core objective is to minimize post_residual (Best Fit), but we penalize 
