    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if the existing options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is high, 
        // suggesting current bins are already cluttered, or if there are no fitting bins.
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            // Otherwise, heavily penalize opening a new bin to force reuse.
            score += 45.0 + (mean_residual * 0.5);
        }
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item, 
    // but the fit is very poor, we might prefer to wait for a new bin.
    if fitting_bins_count == 1 && post_residual > 40 {
        score += 20.0;
    }

    score
