    // We want to pack tightly to minimize the number of bins.
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values that are small but > 0.
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If the next item could fit better in the current bin's remaining space,
    // we should prioritize bins that leave room for that specific future item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item.
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // Penalize bins that block the next item from fitting here.
        }
