    // Dynamic thresholding: As we approach the end of the stream, be more aggressive about 
    // filling current bins rather than opening new ones.
    if is_new_bin {
        // High penalty for opening new bins if there are open bins that could fit the item.
        // The penalty scales with progress to force consolidation at the end of the stream.
        let openness_factor = (open_bins_count as f64).sqrt();
        score += (40.0 + (progress * 60.0)) * openness_factor;

        // If we are forced to open a new bin, ensure it's not preferred over a good fit.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Encourage using bins that are already "half-full" to keep future options open.
        let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * utilization;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
