    // If post_residual is very small (e.g., < 10), it often becomes unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Further reward if the fit is "tight" (leaving little room for a third item)
        if post_residual - next_item_size < 15 {
            score -= 20.0;
        }
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, 
    // become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress. 
        // Early on, we are more willing to open new bins to keep options open.
        // Late in the game, we heavily penalize new bin creation.
        score += 30.0 + (progress * 50.0);
    }

    // 4. Global State Awareness: If we have many open bins, penalize creating more.
    // If we have few, prioritize filling the existing ones.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, 
    // reduce its score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the 
    // average efficiency of current bins to maintain uniformity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We penalize high post-residuals (dead space) to favor Best-Fit behavior.
    let mut score = post;

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to preserve future capacity in other bins.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 40.0 * (1.0 - progress);
    }

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is a new bin candidate.
    // We only want to open a new bin if the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        // Only open new if we have very few options or if existing bins are too full
        // to accommodate incoming items.
        score += 35.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // Reward keeping the mean residual of bins high (balanced packing).
        // If this bin's post_residual is close to the mean_residual of all bins,
        // it is a "good" fit.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // If this is the last chance for the current item, heavily discount the score
    // to prevent leaving an item stranded.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Nonlinear coupling: As the stream nears the end, become more conservative
    // about creating small dead spaces.
    score += (post * post / bin_capacity as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
