    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 55.0);
    }

    // Lookahead coupling: if the next item is large, prioritize bins that have enough space for it
    // If the current post-residual is smaller than the next item, we penalize it
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && (post_residual as u32) > 0 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Density optimization: favor bins that keep the mean residual low across the set.
    // If this bin's post_residual is significantly higher than the current mean, 
    // it fragments the bin space.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    // Criticality adjustment: if this is the only bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Non-linear coupling: Exponential penalty for leaving small, likely unusable "slivers" (1-9 space)
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
