pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creation of "dead zones" (small residuals that cannot fit common items)
    // We heavily penalize residuals between 1 and 9 as they are likely to be wasted.
    let dead_zone_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward bins that keep the mean residual balanced relative to the remaining space
    // This encourages tight packing early on and more flexible packing later.
    let balance_factor = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, favor larger post_residuals
    // to accommodate the incoming item, otherwise favor the tightest fit (Best Fit).
    let lookahead_penalty = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post < needed {
            (needed - post) * 2.5
        } else {
            (post - needed) * 0.2
        }
    } else {
        0.0
    };

    // Progression coupling: As the stream nears completion, become more aggressive 
    // about filling bins tightly (Best Fit) to avoid opening new ones.
    let progress_weight = 1.0 + (progress * 2.0);

    // New bin logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Assign a base cost that increases with the number of open bins to discourage proliferation.
    let base_score = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 15.0) + (1.0 - progress) * 10.0
    } else {
        post * progress_weight
    };

    base_score + dead_zone_penalty + balance_factor + lookahead_penalty
