    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Penalty for empty bins: Base score reflects space wasted.
    // Logic: 
    // 1. Prioritize Best-Fit (minimizing post_residual).
    // 2. If next_item_size is large, avoid bins that leave little room (dead space).
    // 3. If next_item_size is small, prioritize bins that create a perfect fit for the pair.

    let mut score = post_residual as f64;

    // Penalty for opening a new bin unnecessarily:
    // Only open if current bins are very full or if fitting_bins_count is low.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong disincentive to open new bins if space exists
        } else {
            score -= 20.0; // Allow opening if no other choice
        }
    }

    // Lookahead logic:
    // If we have a next item, try to leave a residual that fits it (Best-Fit for future).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize bins that are too small to fit the next item
            score += 25.0;
        }
    }

    // Balance against mean_residual to prevent fragmentation
    // If this bin's post_residual is significantly lower than the mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.8;
    }

    // Penalty for creating 'dead space' (bins that can't fit the smallest possible item, assume 10)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Start with the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // Penalty for creating "fragmented" space (small, unusable residuals).
    // If post_residual is small (e.g., < 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Global State: Favor filling bins that are already "below average" in residual
    // to keep the distribution of remaining space compact.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Scarcity management: If this is the only bin that can fit the item, 
    // it is highly valuable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New Bin Logic: Discourage opening a new bin unless the remaining capacity 
    // is really poor. We add a significant penalty to new bins (residual == capacity).
    if bin_residual == bin_capacity {
        // The penalty scales with the progress of the stream to allow more freedom early on.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (progress * 20.0);

        // If there are many open bins, opening another is expensive.
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) unless it is a perfect fit.
    // Perfect fits (post == 0) are highly rewarded.
    let fragmentation_penalty = if post == 0.0 {
        -500.0
    } else if post < 15.0 {
        // Punish "slivers" that are too small to fit typical future items
        100.0 / (post + 1.0)
    } else {
        0.0
    };

    // Use lookahead to prioritize bins that can accommodate the next item.
    // If the next item is large, we prefer bins with more remaining space.
    let lookahead_score = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -150.0 * (next_item_size as f64 / 100.0)
        } else {
            50.0 * (next_item_size as f64 / 100.0)
        }
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, become more conservative about 
    // opening new bins. If we are early in the stream, favor keeping bins open.
    let new_bin_penalty = if bin_residual == bin_capacity {
        // The cost of opening a new bin scales with progress and the scarcity of fitting bins.
        (250.0 * (1.0 - progress)) + (50.0 * open_bins_count as f64)
    } else {
        0.0
    };

    // Influence of current bin state relative to the mean.
    // Prefer bins that are "denser" than the mean to keep other bins available.
    let density_score = (post - mean_residual) * 0.5;

    // Combine heuristics. Lower is better.
    post + fragmentation_penalty + lookahead_score + new_bin_penalty + density_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // This is already the base score.

    // 2. Penalty for creating "orphan" space (dead space that is too small for any likely future item).
    // If post_residual is less than the smallest possible item size (10), it's likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 3. Lookahead optimization: If we have a next_item, try to preserve space for it.
    // If the current placement makes the bin unable to fit the next item, penalize if better options exist.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Harmonic class bias: Favor bins that leave a residual which is a multiple of common item sizes (e.g., 20, 25, 50).
    // This helps keep bins "aligned" for future items.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 5.0;
    } else if remainder > 20 {
        score += 5.0;
    }

    // 5. New bin logic: Discourage opening a new bin unless the current fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the existing bins are quite full (forcing a new bin is expensive).
        // Penalty is scaled by mean_residual; if mean_residual is low, bins are already full.
        score += 45.0 + (mean_residual * 0.5);
    }

    // 6. Urgency scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && !is_new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-25 range).
    // If post_residual is in the "danger zone" (1..15), drastically increase the score to avoid it.
    if post_residual > 0 && post_residual < 15 {
