    // 2. Open Bins Pressure: Penalize creating new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless there are no other options or the item is large.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0 + (open_bins_count as f64 * 5.0);
        } else {
            score -= 10.0; // Reward opening a new bin if no other bins fit
        }
    }

    // 3. Lookahead Optimization: If next_item_size is large, favor larger post_residuals
    // to accommodate future items, avoiding tight fits that force new bins later.
    if next_item_size > 50 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            score -= 20.0; // Reward bins that can accommodate the next large item
        }
    }

    // 4. Mean Residual Balancing: If the current bin's residual is significantly
    // better than the global mean, reward the placement to keep usage tight.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We heavily penalize large post_residuals (wasted space).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead matching: If next_item_size fits in the post_residual, 
    // significantly reduce the score to encourage this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
        // Reward creating a "perfect" fit for the next item
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // 3. Mean Residual Balancing: Penalize deviations from the average bin fill.
    // This prevents creating many bins with very low residuals while others remain empty.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), calculate a high cost
    // to discourage opening new bins unless the current options are very poor.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 150.0;

        // If we have few open bins or the current mean residual is very tight, 
        // it is safer to open a new bin than to ruin a good existing bin.
        if open_bins_count < 2 {
            score -= 20.0;
        }

        // If the item itself is very large, opening a new bin is often better
        // than forcing it into a bin that leaves an awkward remainder.
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // 5. Urgency: If this is the only bin that can fit the item, 
    // prioritize it to avoid potentially blocking the item later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: "Lookahead-Aware Best-Fit Decreasing (LABFD) with Penalty for Fragmentation"

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor smaller post-residuals (Best Fit).
    let mut score = post_residual as f64;

