    let stranded_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward bins that keep the post-residual close to the global mean (balancing)
    let balance_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
