    let urgency_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0
    } else {
        0.0
    };

    // Combine factors: prioritize tight fits but penalize stranded space and new bin creation
    let score = post + stranded_penalty + balance_penalty + lookahead_penalty + new_bin_penalty + urgency_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
