        }
        // If we are at the end of the stream, prioritize closing gaps.
        let progress = step_index as f64 / total_items as f64;
        score += (progress * 20.0);
    }

    // 6. Scarcity/Fitting constraint:
    // If this is the last bin that can fit the item, we are forced to pick it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 7. Balance against mean_residual:
    // Avoid bins that deviate significantly from the mean_residual to keep bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with penalty for creating 'unusable' gaps.
    // A gap < 10 is generally useless because min item size is 10.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (gaps smaller than the smallest possible item).
    // If post_residual is in [1, 9], it is effectively wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead: If the next item could have fit in this bin, prioritize keeping space for it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // 3. Pressure management: Discourage opening new bins unless necessary.
    if is_new_bin {
        if open_bins_count > 0 {
            // High penalty for opening a new bin if other bins can accommodate the item.
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // Reward bins that have a residual close to the mean, promoting balanced consolidation.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 4. Critical condition: If this is the only bin that fits the item, make it extremely attractive.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize bins that leave tiny, unusable fragments (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Compatibility: Reward bins that leave a post_residual matching the next_item_size.
    // Ideally, we want post_residual == next_item_size to create a perfect pair.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless the current 
    // open bins are highly fragmented or the fitting_bins_count is low.
    if bin_residual == bin_capacity {
        // Discourage opening a new bin if there are existing bins that fit comfortably.
        score += 40.0;

        // If current mean_residual is very low, we are running out of space, so opening a new bin is better.
        score -= (100.0 - mean_residual) * 0.5;
    }

    // 4. Density Balancing:
    // Avoid creating bins that are significantly less efficient than the current average.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 20.0;
    }

    // 5. Urgency factor:
    // As we reach the end of the stream, prioritize closing bins (minimizing residuals).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // The base score is already post_residual.

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0 * (1.0 - progress); 
    }

    // 3. Fragmentation Avoidance: If this is the last bin that can fit the current item,
    // we are less picky about the residual to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Global State Balancing: If the current bin's residual is significantly better 
    // than the average, we reward it to keep the "good" bins active.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // apply a heavy penalty that scales with the number of open bins and remaining progress.
    // We only open a new bin if the current "best" fit is truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        score = 35.0 + (open_bins_count as f64 * 2.0) + (progress * 15.0);
    }

    // 6. Extreme Residual Penalty: If the post_residual is small but not zero,
    // it often creates "dead space" that cannot fit typical items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space: we prefer smaller residuals (Best Fit)
    // However, we penalize very small residuals (e.g., < 10) that create "dead zones"
    // that are unlikely to fit future items.
    let mut score = post_res + (1.0 / (post_res + 1.0) * 50.0);

    // Lookahead logic: if next_item_size fits, we want to keep space available.
    // We penalize bins that would leave insufficient room for the next item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as we progress through the stream, we become more
    // conservative about opening new bins.
    if bin_residual == bin_capacity {
        // This is a new bin. Assign a cost that increases as we approach the end
        // of the stream, effectively forcing packing into existing bins.
        score = 65.0 + (progress * 35.0);
    } else {
        // If we are in an existing bin, favor bins that align with the mean_residual
        // to keep the packing density uniform.
        let dev = (post_res - mean_residual).abs();
        score += dev * 0.2;

        // If this is the last fitting bin, give it a significant bonus to prevent
        // opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Penalty for having too many open bins
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items (10-30 range)
    // Small residuals are often death-traps for future packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of common item sizes
    // Favor residuals that align with the next item size to maximize bin utilization
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        score += remainder as f64 * 0.5;
    }

    // 3. Lookahead/Urgency Coupling:
    // If this is the only bin that can fit the current item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 4. New Bin Thresholding:
    // Only open a new bin if the current mean_residual is very low (implying we are packed tightly)
    // or if the current item is very large (e.g., > 70) and cannot fit well elsewhere.
    if bin_residual == bin_capacity {
        if item_size > 70 {
            score -= 20.0;
        } else if mean_residual > 25.0 {
            score += 100.0; // Heavily penalize opening new bins if existing ones have space
        } else {
            score += 40.0; // Moderate penalty for opening new bins
        }
    }

    // 5. Progression Scaling:
    // As we approach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

