    // If post_residual is < 10, it is likely unusable as the smallest items are typically 10+.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary (fitting_bins_count == 0).
    // If this is a new bin candidate, add a penalty based on current open bin count to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    } else {
        // 4. Tightness bias: Favor bins that are already "tight" to keep space available for larger items.
        // If the bin is already quite full, reward keeping it that way.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Mean residual balancing: If this bin's post_residual is significantly better than 
    // the mean of other bins, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Core Best-Fit Penalty: Minimize post_residual.
    // However, we penalize very tight fits that leave slivers (< 5) 
    // because they are harder to fill later.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // 2. Lookahead Synergy: If the current post_residual can fit the next item, 
    // reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global Bin Management: 
    // If this is a new bin, penalize it based on how many other bins 
    // could have accepted the current item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0;
        // Discourage opening new bins early in the stream.
        score += (step_index as f64 / total_items as f64) * 10.0;
