    // 4. Mean Residual Balancing:
    // Penalize placements that deviate significantly from the mean residual 
    // of active bins to keep bin utilization uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Last Chance Logic:
    // If this is the only bin that can fit the item, strongly prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
