    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating small "sliver" residuals that are difficult to fill later
    // We penalize residuals in the (0, 10) range heavily as they are unlikely to fit any item
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Lookahead logic: if the next item is large, favor bins that leave enough room for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize if this placement prevents the next item from fitting in this bin
            score += 15.0;
        }
    }

    // Global state awareness: if we are near the end of the stream, prioritize tight packing
    // over maintaining multiple open bins.
    if progress > 0.8 {
        score += (open_bins_count as f64) * 5.0;
    }

    // Heuristic for new bin opening:
    // Only open a new bin if the current fit is extremely poor (large residual)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins could fit the item
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // If no bins fit, we must open a new one; normalize to a neutral value
            score = 30.0;
        }
    } else {
        // Favor bins that result in a residual closest to the global mean, 
        // promoting uniform bin usage (Best-Fit variant)
        let residual_delta = (post_residual as f64 - mean_residual).abs();
        score += residual_delta * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize new bin creation to prioritize existing capacity
    if is_new_bin {
        score += 45.0 + (progress * 20.0);
    }

    // If this is the last chance for this item in existing bins, reward fitting it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Non-linear coupling: penalize small residuals that are "useless" (e.g., < 10)
    // as they prevent future items from fitting.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powf(1.5);
    }

    // Lookahead: If next_item_size is large, avoid creating tight residuals now
    if next_item_size > 0 {
        let combined_size = item_size + next_item_size;
        if combined_size <= bin_capacity && post_residual >= next_item_size {
            // Reward placing current item such that the next one can likely fit
            score -= 10.0 * (1.0 - progress);
        } else if combined_size > bin_capacity && post_residual < next_item_size {
            // Penalty for fragmentation if we can't fit the lookahead
            score += 5.0 * progress;
        }
    }

    // Favor bins that align with the global average residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Exact fit reward: Heavily prioritize perfect packing.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Harmonic Class Logic: Penalize residuals that cannot fit common item sizes.
    // We want to avoid creating small "dead" gaps that are too small for almost anything.
    if post_residual < 10 {
        score += 150.0;
    }

    // 3. Lookahead integration: Try to keep space for the next item.
    // If the next item fits into the current post_residual, reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 100.0;
        // Further reward if it leaves a small remainder after the next item (synergy)
        if (post_residual - next_item_size) < 10 {
            score -= 50.0;
        }
    }

    // 4. Bin consolidation: Encourage filling existing bins if they are already partially full.
    // Use the mean_residual to determine if we are being too "loose" with bin space.
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // 5. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        score += 80.0;
        // If we have many open bins, penalize opening another one.
        score += (open_bins_count as f64) * 5.0;
    }

    // 6. Last chance logic:
    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // We should be very favorable to this bin to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 7. Progress scaling: Be more conservative with space as we reach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it falls into the "unusable" range (1..10).
    // Small gaps are the primary cause of inefficiency.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin (bin_residual == bin_capacity)
    // based on how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Fitting Constraint: If this is the last fitting bin, prioritize it to avoid 
    // unnecessary new bin creation, unless the post_residual creates a critical dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Mean Residual Coupling: Favor bins that stay close to the global mean to 
    // keep bin contents uniform, reducing the variance of future fit opportunities.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Progress Scaling: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin heavily unless necessary
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 2. Best-Fit Decreasing logic: penalize large post_residuals (dead space)
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead Matching: Reward bins that create a post_residual 
    // that can perfectly or nearly accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the next item
            let delta = (post_residual - next_item_size) as f64;
            score -= (10.0 / (1.0 + delta));
        } else {
            // Penalize creating a bin that cannot fit the next item 
            // if we are nearing the end of the stream
            let progress = step_index as f64 / total_items as f64;
            score += (1.0 - progress) * 5.0;
        }
    }

    // 4. Balance: Avoid creating bins with residuals significantly lower than the mean
    // unless it results in a very tight fit (Best-Fit principle).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 2.0;
    }

    // 5. Critical Threshold: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}
